import React, { useState, useRef, useEffect } from 'react';
import { GameStats, TurnData, HistoryEntry, Choice } from '../types';
import { processTurn } from '../services/geminiService';
import { StatBar } from './StatBar';
import { Send, AlertTriangle, RefreshCw, Archive, Sparkles } from 'lucide-react';

interface GameInterfaceProps {
  initialTurn: TurnData;
  onRestart: () => void;
}

export const GameInterface: React.FC<GameInterfaceProps> = ({ initialTurn, onRestart }) => {
  // Game State
  const [history, setHistory] = useState<HistoryEntry[]>([{
    turnNumber: 1,
    year: initialTurn.year,
    narrative: initialTurn.narrative,
    eventTitle: initialTurn.eventTitle,
    statsSnapshot: initialTurn.stats,
  }]);

  const [currentTurnData, setCurrentTurnData] = useState<TurnData>(initialTurn);
  const [loading, setLoading] = useState(false);
  const [customInput, setCustomInput] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Refs for auto-scrolling
  const historyEndRef = useRef<HTMLDivElement>(null);

  // Scroll to bottom when history updates
  useEffect(() => {
    historyEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [history, loading]);

  const handleTurn = async (choiceText: string, isCustom: boolean = false) => {
    if (loading || currentTurnData.gameOver) return;

    setLoading(true);
    setError(null);

    // Update history with the user's choice for the PREVIOUS turn (which is the current one before processing)
    const updatedHistory = [...history];
    updatedHistory[updatedHistory.length - 1].userChoice = choiceText;
    setHistory(updatedHistory);

    try {
      const nextTurnData = await processTurn(updatedHistory, choiceText, isCustom ? choiceText : undefined);

      const newEntry: HistoryEntry = {
        turnNumber: updatedHistory.length + 1,
        year: nextTurnData.year,
        narrative: nextTurnData.narrative,
        eventTitle: nextTurnData.eventTitle,
        statsSnapshot: nextTurnData.stats,
      };

      setHistory(prev => [...prev, newEntry]);
      setCurrentTurnData(nextTurnData);
      setCustomInput('');
    } catch (err) {
      setError("The timelines are desynchronizing. The engine failed to process the turn. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const renderChoiceButton = (choice: Choice) => {
    let borderColor = 'border-gray-600 hover:border-gray-400';
    let icon = null;

    if (choice.type === 'aggressive') {
      borderColor = 'border-red-800 hover:border-red-500';
    } else if (choice.type === 'diplomatic') {
      borderColor = 'border-blue-800 hover:border-blue-500';
    } else if (choice.type === 'economic') {
      borderColor = 'border-yellow-800 hover:border-yellow-500';
    }

    return (
      <button
        key={choice.id}
        onClick={() => handleTurn(choice.text)}
        disabled={loading}
        className={`w-full text-left p-4 rounded-lg border ${borderColor} bg-gray-800/80 hover:bg-gray-700 transition-all duration-200 group relative overflow-hidden`}
      >
        <div className="relative z-10">
          <span className="text-xs uppercase tracking-widest opacity-50 block mb-1 font-mono">{choice.type}</span>
          <span className="text-gray-200 group-hover:text-white font-medium">{choice.text}</span>
        </div>
      </button>
    );
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-200 font-serif">
      {/* Top Bar */}
      <StatBar stats={currentTurnData.stats} year={currentTurnData.year} />

      {/* Main Narrative Area */}
      <div className="flex-grow overflow-y-auto p-4 md:p-8 space-y-8 max-w-4xl mx-auto w-full pb-64">
        {history.map((entry, index) => (
          <div key={index} className={`animate-fade-in ${index === history.length - 1 ? 'opacity-100' : 'opacity-70'}`}>
            <div className="flex items-center gap-4 mb-4 opacity-50">
              <div className="h-px bg-gray-700 flex-grow"></div>
              <span className="text-xs font-mono uppercase tracking-widest text-emerald-500">
                {index === 0 ? 'Divergence Point' : `Turn ${entry.turnNumber}`}
              </span>
              <div className="h-px bg-gray-700 flex-grow"></div>
            </div>

            <div className="bg-gray-900 border-l-4 border-emerald-900/50 p-6 rounded-r-lg shadow-sm">
              <h2 className="text-2xl text-emerald-100 font-bold mb-4 font-serif">{entry.eventTitle}</h2>
              <p className="text-lg leading-relaxed text-gray-300 whitespace-pre-wrap">{entry.narrative}</p>

              {entry.userChoice && (
                 <div className="mt-6 pt-4 border-t border-gray-800">
                   <p className="text-sm font-mono text-gray-500">
                     <span className="text-emerald-700">►</span> DECISION RECORDED: {entry.userChoice}
                   </p>
                 </div>
              )}
            </div>
          </div>
        ))}

        {loading && (
          <div className="flex items-center justify-center py-12 animate-pulse gap-3 text-emerald-500">
            <RefreshCw className="animate-spin" />
            <span className="font-mono text-sm uppercase tracking-widest">Simulating Future...</span>
          </div>
        )}

        {error && (
            <div className="bg-red-900/20 border border-red-800 text-red-300 p-4 rounded flex items-center gap-3">
                <AlertTriangle />
                <p>{error}</p>
                <button onClick={() => setError(null)} className="ml-auto underline">Dismiss</button>
            </div>
        )}

        {currentTurnData.gameOver && !loading && (
           <div className="bg-gray-800 border border-yellow-700 p-8 rounded-xl text-center shadow-2xl">
              <h3 className="text-3xl font-bold text-yellow-500 mb-4">Timeline Terminated</h3>
              <p className="text-gray-300 mb-6">The simulation has reached a conclusion.</p>
              <button 
                onClick={onRestart}
                className="bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-3 rounded-lg font-bold shadow-lg transition-transform hover:scale-105"
              >
                Initialize New Divergence
              </button>
           </div>
        )}

        <div ref={historyEndRef} />
      </div>

      {/* Footer Controls */}
      {!currentTurnData.gameOver && (
        <div className="fixed bottom-0 left-0 w-full bg-gray-900/95 backdrop-blur-md border-t border-gray-800 p-4 z-20 shadow-[0_-10px_40px_rgba(0,0,0,0.5)]">
            <div className="max-w-4xl mx-auto">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                    {currentTurnData.choices.map(renderChoiceButton)}
                </div>

                <div className="relative">
                    <input
                        type="text"
                        value={customInput}
                        onChange={(e) => setCustomInput(e.target.value)}
                        placeholder="Or enact a custom directive..."
                        className="w-full bg-gray-950 border border-gray-700 rounded-lg pl-4 pr-12 py-3 focus:outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 text-sm font-mono"
                        onKeyDown={(e) => e.key === 'Enter' && customInput && handleTurn(customInput, true)}
                        disabled={loading}
                    />
                    <button 
                        onClick={() => customInput && handleTurn(customInput, true)}
                        disabled={!customInput || loading}
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-emerald-500 hover:text-emerald-300 disabled:opacity-30 disabled:hover:text-emerald-500 transition-colors"
                    >
                        <Send size={18} />
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { GameStatus, TurnData } from './types';
import { initializeGame } from './services/geminiService';
import { ScenarioSelector } from './components/ScenarioSelector';
import { GameInterface } from './components/GameInterface';
import { RefreshCw, Zap } from 'lucide-react';

const App: React.FC = () => {
  const [status, setStatus] = useState<GameStatus>(GameStatus.MENU);
  const [initialTurnData, setInitialTurnData] = useState<TurnData | null>(null);
  const [loadingError, setLoadingError] = useState<string | null>(null);

  const handleStartGame = async (context: string) => {
    setStatus(GameStatus.LOADING);
    setLoadingError(null);
    try {
      const data = await initializeGame(context);
      setInitialTurnData(data);
      setStatus(GameStatus.PLAYING);
    } catch (error) {
      console.error(error);
      setLoadingError("Failed to initialize the timeline. The AI engine may be overloaded or the API key invalid.");
      setStatus(GameStatus.MENU);
    }
  };

  const handleRestart = () => {
    setStatus(GameStatus.MENU);
    setInitialTurnData(null);
  };

  return (
    <div className="min-h-screen bg-gray-950 text-gray-100 flex flex-col">
      {status === GameStatus.MENU && (
        <div className="flex-grow flex flex-col items-center justify-center p-4">
           {loadingError && (
             <div className="mb-6 p-4 bg-red-900/30 border border-red-700 rounded text-red-200 max-w-md text-center">
               {loadingError}
             </div>
           )}
           <ScenarioSelector onSelect={handleStartGame} />
        </div>
      )}

      {status === GameStatus.LOADING && (
        <div className="flex-grow flex flex-col items-center justify-center p-4 space-y-6 animate-pulse">
           <Zap size={64} className="text-emerald-400" />
           <h2 className="text-3xl font-mono font-bold text-emerald-500 tracking-widest">BUILDING WORLD STATE</h2>
           <p className="text-gray-500 font-mono">Calculating historical trajectories...</p>
           <div className="w-64 h-2 bg-gray-800 rounded-full overflow-hidden">
             <div className="h-full bg-emerald-500 animate-[width_2s_ease-in-out_infinite]" style={{ width: '50%' }}></div>
           </div>
        </div>
      )}

      {status === GameStatus.PLAYING && initialTurnData && (
        <GameInterface initialTurn={initialTurnData} onRestart={handleRestart} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { GameStats, TurnData, HistoryEntry, Choice } from '../types';
import { processTurn } from '../services/geminiService';
import { StatBar } from './StatBar';
import { Send, AlertTriangle, RefreshCw, Archive, Sparkles } from 'lucide-react';

interface GameInterfaceProps {
  initialTurn: TurnData;
  onRestart: () => void;
}

export const GameInterface: React.FC<GameInterfaceProps> = ({ initialTurn, onRestart }) => {
  // Game State
  const [history, setHistory] = useState<HistoryEntry[]>([{
    turnNumber: 1,
    year: initialTurn.year,
    narrative: initialTurn.narrative,
    eventTitle: initialTurn.eventTitle,
    statsSnapshot: initialTurn.stats,
  }]);

  const [currentTurnData, setCurrentTurnData] = useState<TurnData>(initialTurn);
  const [loading, setLoading] = useState(false);
  const [customInput, setCustomInput] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Refs for auto-scrolling
  const historyEndRef = useRef<HTMLDivElement>(null);

  // Scroll to bottom when history updates
  useEffect(() => {
    // Small timeout to allow layout to adjust before scrolling
    const timer = setTimeout(() => {
      historyEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
    return () => clearTimeout(timer);
  }, [history, loading]);

  const handleTurn = async (choiceText: string, isCustom: boolean = false) => {
    if (loading || currentTurnData.gameOver) return;

    setLoading(true);
    setError(null);

    // Update history with the user's choice for the PREVIOUS turn (which is the current one before processing)
    const updatedHistory = [...history];
