import { GoogleGenAI, Type, Schema } from "@google/genai";
import { GameStats, TurnData, HistoryEntry } from '../types';

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY environment variable is not set.");
  }
  return new GoogleGenAI({ apiKey });
};

// Defined schema for strictly structured game output
const turnSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    year: { type: Type.STRING, description: "The current year or date of the game world." },
    eventTitle: { type: Type.STRING, description: "A short, dramatic title for the current turn's main event." },
    narrative: { type: Type.STRING, description: "The main story text describing the current situation, consequences of previous actions, and the state of the world. Approx 100-150 words." },
    stats: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER, description: "Social stability/happiness (0-100)." },
        wealth: { type: Type.INTEGER, description: "Economic prosperity (0-100)." },
        military: { type: Type.INTEGER, description: "Military strength/security (0-100)." },
        population: { type: Type.INTEGER, description: "General population health/growth (0-100)." },
      },
      required: ["stability", "wealth", "military", "population"]
    },
    statsDelta: {
      type: Type.OBJECT,
      description: "The numerical change in stats compared to the previous turn (e.g., -5, +10).",
      properties: {
        stability: { type: Type.INTEGER },
        wealth: { type: Type.INTEGER },
        military: { type: Type.INTEGER },
        population: { type: Type.INTEGER },
      },
      required: ["stability", "wealth", "military", "population"]
    },
    statsReasoning: { 
      type: Type.STRING, 
      description: "1-2 sentences concisely explaining strictly WHY the stats changed this turn (e.g. 'Military spending drained the treasury, but secured the borders.')." 
    },
    choices: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          text: { type: Type.STRING, description: "The description of the action the player can take." },
          type: { type: Type.STRING, enum: ['diplomatic', 'aggressive', 'economic', 'technological'] }
        },
        required: ["id", "text", "type"]
      }
    },
    gameOver: { type: Type.BOOLEAN, description: "True if the player has either achieved a utopia, been conquered, or the regime collapsed." }
  },
  required: ["year", "eventTitle", "narrative", "stats", "statsDelta", "statsReasoning", "choices", "gameOver"]
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();

  const prompt = `
    You are the Game Engine for a text-based alternate history strategy game.

    SCENARIO CONTEXT:
    ${scenarioContext}

    YOUR GOAL:
    Initialize the game at the start of this historical divergence. 
    Describe the initial state of the world immediately following the critical event.
    Establish the player's role (e.g., Leader, Advisor, Hidden Hand).

    RULES:
    - Narrative should be immersive, historical, and serious.
    - Set initial stats based on the scenario difficulty (usually 40-60 range).
    - Determine the 'Impact' of this divergence as the 'statsDelta' (how did this event change the world relative to the status quo?).
    - Provide 3 distinct starting strategic choices.
    - Return the response strictly in JSON format matching the schema.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 } // Use thinking for initial world-building consistency
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Failed to init game:", error);
    throw error;
  }
};

export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  // Construct a concise context of the last few turns to maintain memory without blowing tokens
  // We prioritize the most recent 3 turns + the very first turn (setup)
  const recentHistory = currentHistory.slice(-3);
  const startState = currentHistory[0];

  const historySummary = recentHistory.map(h => 
    `[Year ${h.year}] Event: ${h.eventTitle}. Status: Stability ${h.statsSnapshot.stability}, Wealth ${h.statsSnapshot.wealth}. User Choice: ${h.userChoice || "None"}`
  ).join("\n");

  const latestState = currentHistory[currentHistory.length - 1];

  const actionDescription = customInput 
    ? `Player input a custom unconventional action: "${customInput}"` 
    : `Player selected choice: "${playerChoiceText}"`;

  const prompt = `
    CONTINUE THE ALTERNATE HISTORY GAME.

    STARTING PREMISE (Turn 1): ${startState.narrative.substring(0, 100)}...

    RECENT HISTORY:
    ${historySummary}

    CURRENT STATE (Year ${latestState.year}):
    Stability: ${latestState.statsSnapshot.stability}
    Wealth: ${latestState.statsSnapshot.wealth}
    Military: ${latestState.statsSnapshot.military}
    Pop: ${latestState.statsSnapshot.population}

    PLAYER ACTION:
    ${actionDescription}

    INSTRUCTIONS:
    1. Advance time appropriately (months or years depending on the pace).
    2. Calculate consequences of the player's action on the world state.
    3. Update the narrative and stats.
    4. Calculate the 'statsDelta' (exactly how much each stat added or subtracted this turn).
    5. Provide 'statsReasoning' explaining the cause of these changes.
    6. If stats drop to 0, trigger Game Over (Collapse). If stats average > 90, trigger Game Over (Golden Age).
    7. Provide 3-4 new strategic choices relevant to the new situation.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 4096 } // More thinking for complex consequence logic
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

