import { Send, AlertTriangle, RefreshCw, Terminal, TrendingUp, TrendingDown, Minus } from 'lucide-react';

interface GameInterfaceProps {
  initialTurn: TurnData;
  onRestart: () => void;
}

export const GameInterface: React.FC<GameInterfaceProps> = ({ initialTurn, onRestart }) => {
  // Game State
  const [history, setHistory] = useState<HistoryEntry[]>([{
    turnNumber: 1,
    year: initialTurn.year,
    narrative: initialTurn.narrative,
    eventTitle: initialTurn.eventTitle,
    statsSnapshot: initialTurn.stats,
    statsDelta: initialTurn.statsDelta,
    statsReasoning: initialTurn.statsReasoning,
  }]);

  const [currentTurnData, setCurrentTurnData] = useState<TurnData>(initialTurn);
  const [loading, setLoading] = useState(false);
  const [customInput, setCustomInput] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Refs
  const lastTurnRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
    }
  }, [customInput]);

  // Scroll to the top of the new turn when it arrives
  useEffect(() => {
    const timer = setTimeout(() => {
      // We only scroll if we are not loading (meaning a new turn just arrived or initial load)
      if (!loading && lastTurnRef.current) {
        lastTurnRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }, 100);
    return () => clearTimeout(timer);
  }, [history.length, loading]);

  const handleTurn = async (choiceText: string, isCustom: boolean = false) => {
    if (loading || currentTurnData.gameOver) return;

    setLoading(true);
    setError(null);

    // Update history with the user's choice for the PREVIOUS turn
    const updatedHistory = [...history];
    updatedHistory[updatedHistory.length - 1].userChoice = choiceText;
    setHistory(updatedHistory);

    try {
      const nextTurnData = await processTurn(updatedHistory, choiceText, isCustom ? choiceText : undefined);

      const newEntry: HistoryEntry = {
        turnNumber: updatedHistory.length + 1,
        year: nextTurnData.year,
        narrative: nextTurnData.narrative,
        eventTitle: nextTurnData.eventTitle,
        statsSnapshot: nextTurnData.stats,
        statsDelta: nextTurnData.statsDelta,
        statsReasoning: nextTurnData.statsReasoning,
      };

      setHistory(prev => [...prev, newEntry]);
      setCurrentTurnData(nextTurnData);
      setCustomInput('');
    } catch (err) {
      setError("The timelines are desynchronizing. The engine failed to process the turn. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const renderDelta = (val: number) => {
    if (val > 0) return <span className="text-emerald-400 flex items-center gap-1 text-xs"><TrendingUp size={12} /> +{val}</span>;
    if (val < 0) return <span className="text-red-400 flex items-center gap-1 text-xs"><TrendingDown size={12} /> {val}</span>;
    return <span className="text-gray-600 flex items-center gap-1 text-xs"><Minus size={12} /> -</span>;
  };

  const renderChoiceButton = (choice: Choice) => {
    let borderColor = 'border-gray-700 hover:border-gray-500';
    let typeColor = 'text-gray-500';

    if (choice.type === 'aggressive') {
      borderColor = 'border-red-900/50 hover:border-red-500';
      typeColor = 'text-red-500';
    } else if (choice.type === 'diplomatic') {
      borderColor = 'border-blue-900/50 hover:border-blue-500';
      typeColor = 'text-blue-500';
    } else if (choice.type === 'economic') {
      borderColor = 'border-yellow-900/50 hover:border-yellow-500';
      typeColor = 'text-yellow-500';
    } else if (choice.type === 'technological') {
      borderColor = 'border-purple-900/50 hover:border-purple-500';
      typeColor = 'text-purple-500';
    }

    return (
      <button
        key={choice.id}
        onClick={() => handleTurn(choice.text)}
        disabled={loading}
        className={`w-full text-left p-5 rounded-lg border ${borderColor} bg-gray-900 hover:bg-gray-800 transition-all duration-200 group relative overflow-hidden shadow-md`}
      >
        <div className="relative z-10">
          <span className={`text-xs uppercase tracking-widest font-mono mb-2 block ${typeColor}`}>{choice.type}</span>
          <span className="text-gray-200 group-hover:text-white font-medium leading-snug">{choice.text}</span>
        </div>
      </button>
    );
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-200 font-serif">
      {/* Top Bar - Static */}
      <StatBar stats={currentTurnData.stats} year={currentTurnData.year} />

      {/* Main Narrative Area - Scrollable */}
      <div className="flex-grow overflow-y-auto scroll-smooth">
        <div className="max-w-3xl mx-auto p-4 md:p-8 pb-24 space-y-12">

          {history.map((entry, index) => (
            <div 
              key={index} 
              ref={index === history.length - 1 ? lastTurnRef : null}
              className={`animate-fade-in ${index === history.length - 1 ? 'opacity-100' : 'opacity-80 hover:opacity-100 transition-opacity'}`}
            >
              <div className="flex items-center gap-4 mb-6 opacity-40">
                <div className="h-px bg-gray-700 flex-grow"></div>
                <span className="text-xs font-mono uppercase tracking-widest text-emerald-500">
                  {index === 0 ? 'Divergence Point' : `Turn ${entry.turnNumber}`}
                </span>
                <div className="h-px bg-gray-700 flex-grow"></div>
              </div>

              <div className="space-y-4">
                <h2 className="text-3xl text-emerald-100 font-bold font-serif">{entry.eventTitle}</h2>
                <div className="prose prose-invert prose-lg max-w-none text-gray-300 leading-loose">
                    <p className="whitespace-pre-wrap">{entry.narrative}</p>
                </div>

                {/* Stats Report Card */}
                <div className="bg-gray-900/80 border border-gray-800 rounded-lg p-4 mt-4 font-mono text-sm">
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-3 border-b border-gray-800 pb-3">
                     <div className="flex flex-col">
                        <span className="text-gray-500 text-xs uppercase">Stability</span>
                        <div className="flex items-center gap-2">
                           <span className="font-bold">{entry.statsSnapshot.stability}</span>
                           {renderDelta(entry.statsDelta.stability)}
                        </div>
                     </div>
                     <div className="flex flex-col">
                        <span className="text-gray-500 text-xs uppercase">Wealth</span>
                        <div className="flex items-center gap-2">
                           <span className="font-bold">{entry.statsSnapshot.wealth}</span>
                           {renderDelta(entry.statsDelta.wealth)}
                        </div>
                     </div>
                     <div className="flex flex-col">
                        <span className="text-gray-500 text-xs uppercase">Military</span>
                        <div className="flex items-center gap-2">
                           <span className="font-bold">{entry.statsSnapshot.military}</span>
                           {renderDelta(entry.statsDelta.military)}
                        </div>
                     </div>
                     <div className="flex flex-col">
                        <span className="text-gray-500 text-xs uppercase">Population</span>
                        <div className="flex items-center gap-2">
                           <span className="font-bold">{entry.statsSnapshot.population}</span>
                           {renderDelta(entry.statsDelta.population)}
                        </div>
                     </div>
                  </div>
                  <p className="text-gray-400 italic text-xs leading-relaxed">
                     <span className="text-emerald-500/70 not-italic mr-2">REPORT:</span>
                     {entry.statsReasoning}
                  </p>
                </div>

                {entry.userChoice && (
                   <div className="bg-gray-900/50 border-l-2 border-emerald-700 pl-4 py-2 mt-4 rounded-r">
                     <p className="text-xs font-mono text-emerald-600 mb-1 uppercase tracking-wider">Historical Record</p>
                     <p className="text-sm text-gray-400 italic">"{entry.userChoice}"</p>
                   </div>
                )}
              </div>
            </div>
          ))}

          {loading && (
            <div className="flex flex-col items-center justify-center py-12 animate-pulse gap-4 text-emerald-500/70">
              <RefreshCw className="animate-spin w-8 h-8" />
              <span className="font-mono text-sm uppercase tracking-widest">Calculations in progress...</span>
            </div>
          )}

          {error && (
              <div className="bg-red-900/20 border border-red-800 text-red-300 p-6 rounded-lg flex items-start gap-4">
                  <AlertTriangle className="flex-shrink-0 mt-1" />
                  <div>
                    <p className="font-bold mb-1">Simulation Error</p>
                    <p className="text-sm">{error}</p>
                    <button onClick={() => setError(null)} className="mt-2 text-xs underline hover:text-white">Dismiss</button>
                  </div>
              </div>
          )}

          {/* Controls Section - Inline Flow */}
          {!currentTurnData.gameOver && !loading && (
             <div className="mt-12 border-t-2 border-dashed border-gray-800 pt-8 animate-fade-in">
                 <div className="flex items-center gap-3 mb-6">
                     <Terminal size={18} className="text-emerald-500" />
                     <h3 className="text-sm font-mono text-emerald-500 uppercase tracking-widest">Awaiting Command</h3>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                    {currentTurnData.choices.map(renderChoiceButton)}
                 </div>

                 <div className="relative group">
                    <div className="absolute -inset-0.5 bg-gradient-to-r from-emerald-900 to-blue-900 rounded-lg blur opacity-20 group-hover:opacity-40 transition duration-1000"></div>
                    <div className="relative flex items-end bg-gray-950 rounded-lg border border-gray-700 shadow-inner">
                        <textarea
                            ref={textareaRef}
                            value={customInput}
                            onChange={(e) => setCustomInput(e.target.value)}
                            placeholder="Enter a custom directive manually..."
                            rows={1}
                            className="w-full bg-transparent border-none rounded-lg pl-5 pr-14 py-4 focus:ring-0 text-base font-mono resize-none overflow-hidden"
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && !e.shiftKey) {
                                    e.preventDefault();
                                    if(customInput) handleTurn(customInput, true);
                                }
                            }}
                        />
                        <button 
                            onClick={() => customInput && handleTurn(customInput, true)}
                            disabled={!customInput}
                            className="absolute right-3 bottom-3 p-2 bg-emerald-900/20 text-emerald-500 hover:bg-emerald-800 hover:text-emerald-100 rounded-md transition-all disabled:opacity-0 disabled:pointer-events-none"
                        >
