export interface GameStats {
  stability: number;
  wealth: number;
  military: number;
  population: number; // Abstracted score 0-100
}

export interface WorldLedger {
  diplomaticStatus: string[]; // e.g. ["Turkey: Demilitarized", "USSR: Hotline Active"]
  activeConflicts: string[];  // e.g. ["Atlantic Naval Blockade"]
  domesticPolicies: string[]; // e.g. ["Martial Law", "Rationing"]
  keyFigures: string[];       // e.g. ["Gen. LeMay: Resigned"]
}

export interface Choice {
  id: string;
  text: string;
  type: 'diplomatic' | 'aggressive' | 'economic' | 'technological';
}

export interface TurnData {
  year: string;
  narrative: string;
  stats: GameStats;
  statsDelta: GameStats; 
  statsReasoning: string; 
  ledger: WorldLedger; // The persistent memory bank
  choices: Choice[];
  gameOver: boolean;
  eventTitle: string;
}

export interface HistoryEntry {
  turnNumber: number;
  year: string;
  narrative: string;
  eventTitle: string;
  statsSnapshot: GameStats;
  statsDelta: GameStats;
  statsReasoning: string;
  ledgerSnapshot: WorldLedger;
  userChoice?: string;
}

export interface Scenario {
  id: string;
  title: string;
  description: string;
  startingYear: string;
  imageUrl: string;
  promptContext: string;
}

export enum GameStatus {
  MENU = 'MENU',
  LOADING = 'LOADING',
  PLAYING = 'PLAYING',
  ENDED = 'ENDED'
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { GameStats, TurnData, HistoryEntry, WorldLedger } from '../types';

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY environment variable is not set.");
  }
  return new GoogleGenAI({ apiKey });
};

// Expanded schema to include the World Ledger
