      }
    },
    gameOver: { type: Type.BOOLEAN }
  },
  required: ["year", "eventTitle", "narrative", "stats", "statsDelta", "statsReasoning", "ledger", "choices", "gameOver"]
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();

  const prompt = `
    You are the Game Engine for a deep, text-based alternate history strategy game.

    SCENARIO:
    ${scenarioContext}

    YOUR GOAL:
    Initialize the game. Establish the "World Ledger" which tracks specific facts about the world state.

    INSTRUCTIONS:
    - Create a serious, immersive narrative (approx 150 words).
    - Initialize the 'stats' (0-100).
    - Initialize the 'ledger' with the starting facts of this scenario.
    - Provide 3 strategic choices.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Failed to init game:", error);
    throw error;
  }
};

export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  // STRATEGY FOR LONG-TERM MEMORY (50+ TURNS):
  // 1. We pass the *entire* list of past events (summarized) so the AI sees the full timeline.
  // 2. We pass the *current* World Ledger as the absolute source of truth for facts.

  const fullHistoryLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Stats: S:${h.statsSnapshot.stability} W:${h.statsSnapshot.wealth} M:${h.statsSnapshot.military} P:${h.statsSnapshot.population}`
  ).join("\n");

  const latestState = currentHistory[currentHistory.length - 1];
  const currentLedger = latestState.ledgerSnapshot;

  const actionDescription = customInput 
    ? `Player input custom directive: "${customInput}"` 
    : `Player selected: "${playerChoiceText}"`;

  const prompt = `
    CONTINUE THE ALTERNATE HISTORY TIMELINE.

    === THE ARCHIVES (PAST HISTORY) ===
    ${fullHistoryLog}

    === CURRENT WORLD LEDGER (SOURCE OF TRUTH) ===
    Diplomatic Status: ${JSON.stringify(currentLedger.diplomaticStatus)}
    Active Conflicts: ${JSON.stringify(currentLedger.activeConflicts)}
    Domestic Policies: ${JSON.stringify(currentLedger.domesticPolicies)}
    Key Figures: ${JSON.stringify(currentLedger.keyFigures)}

    === CURRENT SITUATION (Year ${latestState.year}) ===
    Narrative Context: ${latestState.narrative.substring(latestState.narrative.length - 300)}...
    Stats: Stability ${latestState.statsSnapshot.stability}, Wealth ${latestState.statsSnapshot.wealth}, Military ${latestState.statsSnapshot.military}, Pop ${latestState.statsSnapshot.population}

    === PLAYER ACTION ===
    ${actionDescription}

    === INSTRUCTIONS ===
    1. Advance the timeline.
    2. Write the next narrative chapter. Reference specific entries from the Ledger or Archives if relevant.
    3. Update the Game Stats.
    4. **UPDATE THE WORLD LEDGER**:
       - Add new facts created by this turn's events (e.g. "Treaty of London signed").
       - Remove facts that are no longer true (e.g. remove "War with France" if peace was signed).
       - Maintain continuity. If the Ledger says "Turkey Demilitarized", do not allow choices that use Turkish bases unless they are re-militarized first.
    5. Provide 3-4 new strategic choices.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 4096 } // Heavy thinking for continuity checks
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { GameStats, TurnData, HistoryEntry, Choice, WorldLedger } from '../types';
import { processTurn } from '../services/geminiService';
import { StatBar } from './StatBar';
import { Send, AlertTriangle, RefreshCw, Terminal, TrendingUp, TrendingDown, Minus, BookOpen, Globe, Gavel, User, Skull } from 'lucide-react';

interface GameInterfaceProps {
  initialTurn: TurnData;
  onRestart: () => void;
}

export const GameInterface: React.FC<GameInterfaceProps> = ({ initialTurn, onRestart }) => {
  // Game State
  const [history, setHistory] = useState<HistoryEntry[]>([{
    turnNumber: 1,
    year: initialTurn.year,
    narrative: initialTurn.narrative,
    eventTitle: initialTurn.eventTitle,
    statsSnapshot: initialTurn.stats,
    statsDelta: initialTurn.statsDelta,
    statsReasoning: initialTurn.statsReasoning,
    ledgerSnapshot: initialTurn.ledger
  }]);

  const [currentTurnData, setCurrentTurnData] = useState<TurnData>(initialTurn);
  const [loading, setLoading] = useState(false);
  const [customInput, setCustomInput] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [showLedger, setShowLedger] = useState(false);

  // Refs
  const lastTurnRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
    }
  }, [customInput]);

  // Scroll to the top of the new turn
  useEffect(() => {
    const timer = setTimeout(() => {
      if (!loading && lastTurnRef.current) {
        lastTurnRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }, 100);
    return () => clearTimeout(timer);
  }, [history.length, loading]);

  const handleTurn = async (choiceText: string, isCustom: boolean = false) => {
    if (loading || currentTurnData.gameOver) return;

    setLoading(true);
    setError(null);

    const updatedHistory = [...history];
    updatedHistory[updatedHistory.length - 1].userChoice = choiceText;
    setHistory(updatedHistory);

    try {
      const nextTurnData = await processTurn(updatedHistory, choiceText, isCustom ? choiceText : undefined);

      const newEntry: HistoryEntry = {
        turnNumber: updatedHistory.length + 1,
        year: nextTurnData.year,
        narrative: nextTurnData.narrative,
        eventTitle: nextTurnData.eventTitle,
        statsSnapshot: nextTurnData.stats,
        statsDelta: nextTurnData.statsDelta,
        statsReasoning: nextTurnData.statsReasoning,
        ledgerSnapshot: nextTurnData.ledger
      };

      setHistory(prev => [...prev, newEntry]);
      setCurrentTurnData(nextTurnData);
      setCustomInput('');
    } catch (err) {
      setError("The timelines are desynchronizing. The engine failed to process the turn. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const renderDelta = (val: number) => {
    if (val > 0) return <span className="text-emerald-400 flex items-center gap-1 text-xs"><TrendingUp size={12} /> +{val}</span>;
    if (val < 0) return <span className="text-red-400 flex items-center gap-1 text-xs"><TrendingDown size={12} /> {val}</span>;
    return <span className="text-gray-600 flex items-center gap-1 text-xs"><Minus size={12} /> -</span>;
  };

  const renderChoiceButton = (choice: Choice) => {
    let borderColor = 'border-gray-700 hover:border-gray-500';
    let typeColor = 'text-gray-500';

    if (choice.type === 'aggressive') {
      borderColor = 'border-red-900/50 hover:border-red-500';
      typeColor = 'text-red-500';
    } else if (choice.type === 'diplomatic') {
      borderColor = 'border-blue-900/50 hover:border-blue-500';
      typeColor = 'text-blue-500';
    } else if (choice.type === 'economic') {
      borderColor = 'border-yellow-900/50 hover:border-yellow-500';
      typeColor = 'text-yellow-500';
    } else if (choice.type === 'technological') {
      borderColor = 'border-purple-900/50 hover:border-purple-500';
      typeColor = 'text-purple-500';
    }

    return (
      <button
        key={choice.id}
        onClick={() => handleTurn(choice.text)}
        disabled={loading}
        className={`w-full text-left p-5 rounded-lg border ${borderColor} bg-gray-900 hover:bg-gray-800 transition-all duration-200 group relative overflow-hidden shadow-md`}
      >
        <div className="relative z-10">
          <span className={`text-xs uppercase tracking-widest font-mono mb-2 block ${typeColor}`}>{choice.type}</span>
          <span className="text-gray-200 group-hover:text-white font-medium leading-snug">{choice.text}</span>
        </div>
      </button>
    );
  };

  const LedgerPanel = ({ ledger }: { ledger: WorldLedger }) => (
    <div className="bg-gray-900/90 border border-gray-700 rounded-lg p-6 mb-8 shadow-2xl animate-fade-in relative overflow-hidden">
      <div className="absolute top-0 right-0 p-4 opacity-10">
         <Globe size={100} />
      </div>
      <h3 className="text-lg font-mono font-bold text-emerald-500 mb-4 flex items-center gap-2">
        <BookOpen size={18} /> WORLD INTELLIGENCE LEDGER
      </h3>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 relative z-10">
        <div>
           <h4 className="text-xs font-bold text-blue-400 uppercase tracking-widest mb-2 flex items-center gap-2"><Globe size={14}/> Diplomatic Status</h4>
           {ledger.diplomaticStatus.length === 0 ? <p className="text-gray-600 text-xs italic">No active treaties.</p> : (
             <ul className="list-disc list-inside text-sm text-gray-300 space-y-1">
               {ledger.diplomaticStatus.map((s, i) => <li key={i}>{s}</li>)}
             </ul>
           )}
        </div>
        <div>
           <h4 className="text-xs font-bold text-red-400 uppercase tracking-widest mb-2 flex items-center gap-2"><Skull size={14}/> Active Conflicts</h4>
           {ledger.activeConflicts.length === 0 ? <p className="text-gray-600 text-xs italic">Global peace (temporary).</p> : (
             <ul className="list-disc list-inside text-sm text-gray-300 space-y-1">
               {ledger.activeConflicts.map((s, i) => <li key={i}>{s}</li>)}
             </ul>
           )}
        </div>
        <div>
           <h4 className="text-xs font-bold text-yellow-400 uppercase tracking-widest mb-2 flex items-center gap-2"><Gavel size={14}/> Domestic Policy</h4>
           {ledger.domesticPolicies.length === 0 ? <p className="text-gray-600 text-xs italic">Standard governance.</p> : (
             <ul className="list-disc list-inside text-sm text-gray-300 space-y-1">
               {ledger.domesticPolicies.map((s, i) => <li key={i}>{s}</li>)}
             </ul>
           )}
        </div>
        <div>
           <h4 className="text-xs font-bold text-purple-400 uppercase tracking-widest mb-2 flex items-center gap-2"><User size={14}/> Key Figures</h4>
           {ledger.keyFigures.length === 0 ? <p className="text-gray-600 text-xs italic">No notable status changes.</p> : (
             <ul className="list-disc list-inside text-sm text-gray-300 space-y-1">
               {ledger.keyFigures.map((s, i) => <li key={i}>{s}</li>)}
             </ul>
           )}
        </div>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-200 font-serif">
      <StatBar stats={currentTurnData.stats} year={currentTurnData.year} />

      <div className="flex-grow overflow-y-auto scroll-smooth">
        <div className="max-w-3xl mx-auto p-4 md:p-8 pb-24 space-y-12">

          {history.map((entry, index) => (
            <div 
              key={index} 
              ref={index === history.length - 1 ? lastTurnRef : null}
              className={`animate-fade-in ${index === history.length - 1 ? 'opacity-100' : 'opacity-80 hover:opacity-100 transition-opacity'}`}
            >
              <div className="flex items-center gap-4 mb-6 opacity-40">
                <div className="h-px bg-gray-700 flex-grow"></div>
                <span className="text-xs font-mono uppercase tracking-widest text-emerald-500">
                  {index === 0 ? 'Divergence Point' : `Turn ${entry.turnNumber}`}
                </span>
                <div className="h-px bg-gray-700 flex-grow"></div>
              </div>

              <div className="space-y-4">
                <h2 className="text-3xl text-emerald-100 font-bold font-serif">{entry.eventTitle}</h2>
                <div className="prose prose-invert prose-lg max-w-none text-gray-300 leading-loose">
                    <p className="whitespace-pre-wrap">{entry.narrative}</p>
                </div>

                {/* Stats Report Card */}
                <div className="bg-gray-900/80 border border-gray-800 rounded-lg p-4 mt-4 font-mono text-sm">
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-3 border-b border-gray-800 pb-3">
                     <div className="flex flex-col">
                        <span className="text-gray-500 text-xs uppercase">Stability</span>
                        <div className="flex items-center gap-2">
                           <span className="font-bold">{entry.statsSnapshot.stability}</span>
                           {renderDelta(entry.statsDelta.stability)}
                        </div>
                     </div>
                     <div className="flex flex-col">
                        <span className="text-gray-500 text-xs uppercase">Wealth</span>
                        <div className="flex items-center gap-2">
                           <span className="font-bold">{entry.statsSnapshot.wealth}</span>
                           {renderDelta(entry.statsDelta.wealth)}
                        </div>
                     </div>
                     <div className="flex flex-col">
                        <span className="text-gray-500 text-xs uppercase">Military</span>
                        <div className="flex items-center gap-2">
                           <span className="font-bold">{entry.statsSnapshot.military}</span>
                           {renderDelta(entry.statsDelta.military)}
                        </div>
                     </div>
                     <div className="flex flex-col">
                        <span className="text-gray-500 text-xs uppercase">Population</span>
                        <div className="flex items-center gap-2">
                           <span className="font-bold">{entry.statsSnapshot.population}</span>
                           {renderDelta(entry.statsDelta.population)}
                        </div>
                     </div>
                  </div>
                  <p className="text-gray-400 italic text-xs leading-relaxed">
                     <span className="text-emerald-500/70 not-italic mr-2">REPORT:</span>
                     {entry.statsReasoning}
                  </p>
                </div>

                {entry.userChoice && (
                   <div className="bg-gray-900/50 border-l-2 border-emerald-700 pl-4 py-2 mt-4 rounded-r">
                     <p className="text-xs font-mono text-emerald-600 mb-1 uppercase tracking-wider">Historical Record</p>
                     <p className="text-sm text-gray-400 italic">"{entry.userChoice}"</p>
                   </div>
                )}
              </div>
            </div>
          ))}

          {loading && (
            <div className="flex flex-col items-center justify-center py-12 animate-pulse gap-4 text-emerald-500/70">
              <RefreshCw className="animate-spin w-8 h-8" />
              <span className="font-mono text-sm uppercase tracking-widest">Processing Historical Trajectory...</span>
            </div>
          )}

          {error && (
              <div className="bg-red-900/20 border border-red-800 text-red-300 p-6 rounded-lg flex items-start gap-4">
                  <AlertTriangle className="flex-shrink-0 mt-1" />
                  <div>
                    <p className="font-bold mb-1">Simulation Error</p>
                    <p className="text-sm">{error}</p>
                    <button onClick={() => setError(null)} className="mt-2 text-xs underline hover:text-white">Dismiss</button>
                  </div>
              </div>
          )}

          {!currentTurnData.gameOver && !loading && (
             <div className="mt-12 pt-8 animate-fade-in">

                 <div className="flex justify-between items-end mb-6">
                    <div className="flex items-center gap-3">
                        <Terminal size={18} className="text-emerald-500" />
                        <h3 className="text-sm font-mono text-emerald-500 uppercase tracking-widest">Awaiting Command</h3>
                    </div>
                    <button 
                        onClick={() => setShowLedger(!showLedger)}
                        className="text-xs font-mono text-blue-400 hover:text-blue-300 uppercase flex items-center gap-2 bg-gray-900 px-3 py-1 rounded border border-blue-900/50 hover:border-blue-500 transition-all"
                    >
                        {showLedger ? 'Hide Intel' : 'View World Intel'}
                    </button>
                 </div>

                 {showLedger && <LedgerPanel ledger={currentTurnData.ledger} />}

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                    {currentTurnData.choices.map(renderChoiceButton)}
                 </div>

                 <div className="relative group">
                    <div className="absolute -inset-0.5 bg-gradient-to-r from-emerald-900 to-blue-900 rounded-lg blur opacity-20 group-hover:opacity-40 transition duration-1000"></div>
                    <div className="relative flex items-end bg-gray-950 rounded-lg border border-gray-700 shadow-inner">
                        <textarea
                            ref={textareaRef}
                            value={customInput}
                            onChange={(e) => setCustomInput(e.target.value)}
                            placeholder="Enter a custom directive manually..."
                            rows={1}
                            className="w-full bg-transparent border-none rounded-lg pl-5 pr-14 py-4 focus:ring-0 text-base font-mono resize-none overflow-hidden"
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && !e.shiftKey) {
                                    e.preventDefault();
                                    if(customInput) handleTurn(customInput, true);
                                }
                            }}
                        />
                        <button 
                            onClick={() => customInput && handleTurn(customInput, true)}
                            disabled={!customInput}
                            className="absolute right-3 bottom-3 p-2 bg-emerald-900/20 text-emerald-500 hover:bg-emerald-800 hover:text-emerald-100 rounded-md transition-all disabled:opacity-0 disabled:pointer-events-none"
                        >
                            <Send size={20} />
                        </button>
                    </div>
                 </div>
             </div>
          )}

          {currentTurnData.gameOver && !loading && (
             <div className="bg-gray-800 border border-yellow-700/50 p-8 rounded-xl text-center shadow-2xl mt-12">
                <h3 className="text-3xl font-bold text-yellow-500 mb-4">Timeline Terminated</h3>
                <p className="text-gray-300 mb-8">The simulation has reached a conclusion.</p>
                <button 
                  onClick={onRestart}
                  className="bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-lg font-bold shadow-lg transition-transform hover:scale-105 uppercase tracking-wide text-sm"
                >
                  Initialize New Divergence
                </button>
             </div>
          )}

          <div className="h-4" />
        </div>
      </div>
    </div>
  );
};

payload.text:
The choices are created through a combination of **Structured Output (JSON Schema)** and **Contextual Inference**.

Here is exactly how it works under the hood right now:

### 1. The Schema ( The "Shape" )
In `services/geminiService.ts`, we defined a strict blueprint that the AI **must** follow. We don't just ask for text; we force the AI to fill out this specific form:

```typescript
// Inside turnSchema
choices: {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.STRING },
      text: { type: Type.STRING },
      // THIS IS THE KEY PART:
      type: { type: Type.STRING, enum: ['diplomatic', 'aggressive', 'economic', 'technological'] }
    }
  }
}
```
Because of the `enum` (enumeration), the AI is **banned** from creating a choice type like "Magic" or "Random." It looks at the story it just wrote, thinks of a valid action, and then acts as a classifier to sort that action into one of your 4 allowed buckets.

### 2. The Context ( The "Brain" )
When the AI generates the narrative (e.g., "The Soviets have blockaded Berlin"), it simultaneously calculates the logical next steps for a leader in that situation.
*   It thinks: "A leader could shoot back." -> Labels this **Aggressive**.
*   It thinks: "A leader could call the UN." -> Labels this **Diplomatic**.
*   It thinks: "A leader could impose sanctions." -> Labels this **Economic**.

### The Improvement
Currently, the prompt simply says *"Provide 3-4 new strategic choices."*

This is a bit weak. It allows the AI to get lazy (e.g., offering 3 Aggressive choices and nothing else).

I am updating the `geminiService.ts` to explicitly instruct the AI to **enforce diversity** in its options. I want to ensure the player always feels like they have different *types* of levers to pull, rather than just different flavors of the same action.

