import { GoogleGenAI, Type, Schema } from "@google/genai";
import { GameStats, TurnData, HistoryEntry, WorldLedger } from '../types';

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY environment variable is not set.");
  }
  return new GoogleGenAI({ apiKey });
};

// Expanded schema to include the World Ledger
const turnSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    year: { type: Type.STRING, description: "The current year or date of the game world." },
    eventTitle: { type: Type.STRING, description: "A short, dramatic title for the current turn's main event." },
    narrative: { type: Type.STRING, description: "The main story text. 150-200 words. Be detailed and reference specific past events if relevant." },
    stats: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER, description: "Social stability/happiness (0-100)." },
        wealth: { type: Type.INTEGER, description: "Economic prosperity (0-100)." },
        military: { type: Type.INTEGER, description: "Military strength/security (0-100)." },
        population: { type: Type.INTEGER, description: "General population health/growth (0-100)." },
      },
      required: ["stability", "wealth", "military", "population"]
    },
    statsDelta: {
      type: Type.OBJECT,
      description: "The numerical change in stats compared to the previous turn.",
      properties: {
        stability: { type: Type.INTEGER },
        wealth: { type: Type.INTEGER },
        military: { type: Type.INTEGER },
        population: { type: Type.INTEGER },
      },
      required: ["stability", "wealth", "military", "population"]
    },
    statsReasoning: { type: Type.STRING, description: "Explanation for stat changes." },
    ledger: {
      type: Type.OBJECT,
      description: "The Persistent World Ledger. You must update this every turn based on the player's choices and narrative outcomes.",
      properties: {
        diplomaticStatus: { 
          type: Type.ARRAY, 
          items: { type: Type.STRING },
          description: "List of active treaties, alliances, or diplomatic statuses (e.g. 'Turkey: Missiles Removed')."
        },
        activeConflicts: { 
          type: Type.ARRAY, 
          items: { type: Type.STRING },
          description: "List of ongoing wars, battles, or blockades."
        },
        domesticPolicies: { 
          type: Type.ARRAY, 
          items: { type: Type.STRING },
          description: "List of active laws or internal states (e.g. 'Martial Law')."
        },
        keyFigures: { 
          type: Type.ARRAY, 
          items: { type: Type.STRING },
          description: "Status of important NPCs (e.g. 'JFK: Deceased', 'Khrushchev: Ousted')."
        }
      },
      required: ["diplomaticStatus", "activeConflicts", "domesticPolicies", "keyFigures"]
    },
    choices: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          text: { type: Type.STRING, description: "A distinct strategic option." },
          type: { type: Type.STRING, enum: ['diplomatic', 'aggressive', 'economic', 'technological'] }
        },
        required: ["id", "text", "type"]
      }
    },
    gameOver: { type: Type.BOOLEAN }
  },
  required: ["year", "eventTitle", "narrative", "stats", "statsDelta", "statsReasoning", "ledger", "choices", "gameOver"]
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();

  const prompt = `
    You are the Game Engine for a deep, text-based alternate history strategy game.

    SCENARIO:
    ${scenarioContext}

