import { GoogleGenAI, Type, Schema } from "@google/genai";
import { GameStats, TurnData, HistoryEntry, WorldLedger } from '../types';

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY environment variable is not set.");
  }
  return new GoogleGenAI({ apiKey });
};

// Complex schema for the Situation Room experience
const turnSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    year: { type: Type.STRING },
    eventTitle: { type: Type.STRING },

    // NEW: Public perception
    news: {
      type: Type.ARRAY,
      description: "3 distinct news headlines reflecting public perception or propaganda.",
      items: {
        type: Type.OBJECT,
        properties: {
          source: { type: Type.STRING, description: "Name of the publication or source (context appropriate)." },
          headline: { type: Type.STRING }
        },
        required: ["source", "headline"]
      }
    },

    // Main Narrative is now treated as "Intelligence Briefing"
    narrative: { type: Type.STRING, description: "The classified situation report. What is REALLY happening? 100-150 words." },

    // NEW: Advisor System
    advisors: {
      type: Type.ARRAY,
      description: "2 Advisors with conflicting viewpoints on the current crisis.",
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          name: { type: Type.STRING },
          role: { type: Type.STRING, description: "Job title (e.g. 'General', 'Minister', 'Spy Master')" },
          advice: { type: Type.STRING, description: "First-person perspective advice urging a specific course of action." },
          bias: { type: Type.STRING, enum: ['aggressive', 'diplomatic', 'economic', 'scientific'] }
        },
        required: ["id", "name", "role", "advice", "bias"]
      }
    },

    stats: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER },
        wealth: { type: Type.INTEGER },
        military: { type: Type.INTEGER },
        population: { type: Type.INTEGER },
      },
      required: ["stability", "wealth", "military", "population"]
    },
    statsDelta: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER },
        wealth: { type: Type.INTEGER },
        military: { type: Type.INTEGER },
        population: { type: Type.INTEGER },
      },
      required: ["stability", "wealth", "military", "population"]
    },
    statsReasoning: { type: Type.STRING },
    ledger: {
      type: Type.OBJECT,
      properties: {
        diplomaticStatus: { type: Type.ARRAY, items: { type: Type.STRING } },
        activeConflicts: { type: Type.ARRAY, items: { type: Type.STRING } },
        domesticPolicies: { type: Type.ARRAY, items: { type: Type.STRING } },
        keyFigures: { type: Type.ARRAY, items: { type: Type.STRING } }
      },
      required: ["diplomaticStatus", "activeConflicts", "domesticPolicies", "keyFigures"]
    },
    choices: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          text: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['diplomatic', 'aggressive', 'economic', 'technological'] },
          risk: { type: Type.STRING, enum: ['LOW', 'MEDIUM', 'HIGH', 'EXTREME'], description: "The estimated risk of failure or blowback." },
          projectedCost: { type: Type.STRING, description: "Short text description of cost (e.g. 'High Military Cost', 'Political Suicide')." }
        },
        required: ["id", "text", "type", "risk"]
      }
    },
    gameOver: { type: Type.BOOLEAN }
  },
  required: ["year", "eventTitle", "news", "narrative", "advisors", "stats", "statsDelta", "statsReasoning", "ledger", "choices", "gameOver"]
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();

  const prompt = `
    You are the Game Engine for "Chronus", a deep alternate history simulator.

    SCENARIO CONTEXT:
    ${scenarioContext}

    YOUR TASK:
    Initialize the game state (Turn 1).

    CRITICAL INSTRUCTIONS FOR DEPTH:
    1. **Advisors**: Generate 2 key advisors suitable for this era (e.g., a Hawk General vs. a Dove Diplomat). They must give conflicting advice.
    2. **News**: Generate 3 headlines that show how the public/media perceives the event (often different from the truth).
    3. **Choices**: Provide 4 choices. Assess their RISK accurately.
    4. **Ledger**: Populate the initial world facts.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Failed to init game:", error);
    throw error;
  }
};

export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  const fullHistoryLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Stats: S:${h.statsSnapshot.stability} W:${h.statsSnapshot.wealth} M:${h.statsSnapshot.military} P:${h.statsSnapshot.population}`
  ).join("\n");

  const latestState = currentHistory[currentHistory.length - 1];
  const currentLedger = latestState.ledgerSnapshot;

  const actionDescription = customInput 
    ? `Player input custom directive: "${customInput}"` 
    : `Player selected: "${playerChoiceText}"`;

  const prompt = `
    CONTINUE THE ALTERNATE HISTORY TIMELINE.

    === ARCHIVES ===
    ${fullHistoryLog}

    === WORLD LEDGER (Facts) ===
    ${JSON.stringify(currentLedger, null, 2)}

    === PREVIOUS SITUATION ===
    Year: ${latestState.year}
    Context: ${latestState.narrative}

    === PLAYER ACTION ===
    ${actionDescription}

    === INSTRUCTIONS ===
    1. **Narrative**: Write a "Classified Intel Report" (150 words) describing the true outcome.
    2. **Public News**: Generate 3 headlines. How does the public react? Panic? Celebration? Ignorance?
    3. **Advisors**: The advisors must react to the new situation. One might say "I told you so," the other might suggest a new plan.
    4. **Ledger**: Update the world facts.
    5. **Choices**: Provide 4 diverse strategic options with clear RISK assessments (LOW/MED/HIGH/EXTREME).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 4096 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { GameStats, TurnData, HistoryEntry, Choice, WorldLedger, Advisor, NewsFlash } from '../types';
import { processTurn } from '../services/geminiService';
import { StatBar } from './StatBar';
import { Send, AlertTriangle, RefreshCw, Terminal, TrendingUp, TrendingDown, Minus, BookOpen, Globe, Gavel, User, Skull, Radio, Lock, MessageSquare } from 'lucide-react';

interface GameInterfaceProps {
  initialTurn: TurnData;
  onRestart: () => void;
}

export const GameInterface: React.FC<GameInterfaceProps> = ({ initialTurn, onRestart }) => {
  // Game State
  const [history, setHistory] = useState<HistoryEntry[]>([{
    turnNumber: 1,
    year: initialTurn.year,
    narrative: initialTurn.narrative,
    eventTitle: initialTurn.eventTitle,
    statsSnapshot: initialTurn.stats,
    statsDelta: initialTurn.statsDelta,
    statsReasoning: initialTurn.statsReasoning,
    ledgerSnapshot: initialTurn.ledger
  }]);

  const [currentTurnData, setCurrentTurnData] = useState<TurnData>(initialTurn);
  const [loading, setLoading] = useState(false);
  const [customInput, setCustomInput] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [showLedger, setShowLedger] = useState(false);

  // Refs
  const lastTurnRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
    }
  }, [customInput]);

  // Scroll to the top of the new turn
  useEffect(() => {
    const timer = setTimeout(() => {
      if (!loading && lastTurnRef.current) {
        lastTurnRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }, 100);
    return () => clearTimeout(timer);
  }, [history.length, loading]);

  const handleTurn = async (choiceText: string, isCustom: boolean = false) => {
    if (loading || currentTurnData.gameOver) return;

    setLoading(true);
    setError(null);

    const updatedHistory = [...history];
    updatedHistory[updatedHistory.length - 1].userChoice = choiceText;
    setHistory(updatedHistory);

    try {
      const nextTurnData = await processTurn(updatedHistory, choiceText, isCustom ? choiceText : undefined);

      const newEntry: HistoryEntry = {
        turnNumber: updatedHistory.length + 1,
        year: nextTurnData.year,
        narrative: nextTurnData.narrative,
        eventTitle: nextTurnData.eventTitle,
        statsSnapshot: nextTurnData.stats,
        statsDelta: nextTurnData.statsDelta,
        statsReasoning: nextTurnData.statsReasoning,
        ledgerSnapshot: nextTurnData.ledger
      };

      setHistory(prev => [...prev, newEntry]);
      setCurrentTurnData(nextTurnData);
      setCustomInput('');
    } catch (err) {
      setError("The timelines are desynchronizing. The engine failed to process the turn. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const renderDelta = (val: number) => {
    if (val > 0) return <span className="text-emerald-400 flex items-center gap-1 text-xs"><TrendingUp size={12} /> +{val}</span>;
    if (val < 0) return <span className="text-red-400 flex items-center gap-1 text-xs"><TrendingDown size={12} /> {val}</span>;
    return <span className="text-gray-600 flex items-center gap-1 text-xs"><Minus size={12} /> -</span>;
  };

  const renderChoiceButton = (choice: Choice) => {
    let borderColor = 'border-gray-700 hover:border-gray-500';
    let typeColor = 'text-gray-500';

    if (choice.type === 'aggressive') {
      borderColor = 'border-red-900/40 hover:border-red-500/80';
      typeColor = 'text-red-500';
    } else if (choice.type === 'diplomatic') {
      borderColor = 'border-blue-900/40 hover:border-blue-500/80';
      typeColor = 'text-blue-500';
    } else if (choice.type === 'economic') {
      borderColor = 'border-yellow-900/40 hover:border-yellow-500/80';
      typeColor = 'text-yellow-500';
    } else if (choice.type === 'technological') {
      borderColor = 'border-purple-900/40 hover:border-purple-500/80';
      typeColor = 'text-purple-500';
    }

    const getRiskColor = (r: string) => {
      switch(r) {
        case 'LOW': return 'bg-emerald-900/50 text-emerald-400';
        case 'MEDIUM': return 'bg-yellow-900/50 text-yellow-400';
        case 'HIGH': return 'bg-orange-900/50 text-orange-400';
        case 'EXTREME': return 'bg-red-900/50 text-red-400';
        default: return 'bg-gray-800 text-gray-400';
      }
    }

    return (
      <button
        key={choice.id}
        onClick={() => handleTurn(choice.text)}
        disabled={loading}
        className={`w-full text-left p-5 rounded-lg border ${borderColor} bg-gray-900/80 hover:bg-gray-800 transition-all duration-200 group relative overflow-hidden shadow-lg flex flex-col gap-3`}
      >
        <div className="flex justify-between items-start w-full">
           <span className={`text-xs uppercase tracking-widest font-mono ${typeColor}`}>{choice.type}</span>
           <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded ${getRiskColor(choice.risk)}`}>
             Risk: {choice.risk}
           </span>
        </div>

        <span className="text-gray-200 group-hover:text-white font-medium leading-snug">{choice.text}</span>

        {choice.projectedCost && (
          <div className="mt-1 pt-2 border-t border-gray-800 w-full">
             <span className="text-xs text-gray-500 italic flex items-center gap-1">
               <AlertTriangle size={10} /> {choice.projectedCost}
             </span>
          </div>
        )}
      </button>
    );
  };

  const AdvisorCard = ({ advisor }: { advisor: Advisor }) => {
    let colorClass = "text-gray-400";
    if (advisor.bias === 'aggressive') colorClass = "text-red-400";
    if (advisor.bias === 'diplomatic') colorClass = "text-blue-400";
    if (advisor.bias === 'economic') colorClass = "text-yellow-400";
    if (advisor.bias === 'scientific') colorClass = "text-purple-400";

    return (
      <div className="bg-gray-900/80 border border-gray-800 p-4 rounded-lg flex items-start gap-4">
         <div className={`w-12 h-12 rounded-full flex items-center justify-center bg-gray-800 border border-gray-700 shrink-0 ${colorClass}`}>
            <User size={24} />
         </div>
         <div>
            <h4 className={`text-sm font-bold ${colorClass} uppercase tracking-wider`}>{advisor.role}</h4>
            <p className="text-xs text-gray-500 mb-2">{advisor.name}</p>
            <div className="bg-black/30 p-2 rounded text-sm italic text-gray-300 border-l-2 border-gray-700">
              "{advisor.advice}"
            </div>
         </div>
      </div>
    );
  };

  const NewsTicker = ({ news }: { news: NewsFlash[] }) => (
    <div className="w-full bg-black/50 border-y border-gray-800 py-2 overflow-hidden mb-6 relative">
       <div className="flex items-center gap-2 absolute left-4 top-2 z-10 bg-black/50 px-2">
         <Radio size={14} className="text-red-500 animate-pulse" />
         <span className="text-xs font-mono text-red-500 uppercase font-bold">Live Wire</span>
       </div>
       <div className="whitespace-nowrap overflow-hidden flex gap-8 pl-32">
         {news.map((n, i) => (
           <span key={i} className="text-sm font-mono text-gray-400 inline-block">
             <span className="text-gray-600 font-bold mr-2">[{n.source}]</span> 
             {n.headline.toUpperCase()}
           </span>
         ))}
       </div>
    </div>
  );

  const LedgerPanel = ({ ledger }: { ledger: WorldLedger }) => (
    <div className="bg-gray-900/90 border border-gray-700 rounded-lg p-6 mb-8 shadow-2xl animate-fade-in relative overflow-hidden">
      <div className="absolute top-0 right-0 p-4 opacity-10">
         <Globe size={100} />
      </div>
      <h3 className="text-lg font-mono font-bold text-emerald-500 mb-4 flex items-center gap-2">
        <BookOpen size={18} /> WORLD INTELLIGENCE LEDGER
      </h3>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 relative z-10">
        <div>
           <h4 className="text-xs font-bold text-blue-400 uppercase tracking-widest mb-2 flex items-center gap-2"><Globe size={14}/> Diplomatic Status</h4>
           {ledger.diplomaticStatus.length === 0 ? <p className="text-gray-600 text-xs italic">No active treaties.</p> : (
             <ul className="list-disc list-inside text-sm text-gray-300 space-y-1">
               {ledger.diplomaticStatus.map((s, i) => <li key={i}>{s}</li>)}
             </ul>
           )}
        </div>
        <div>
           <h4 className="text-xs font-bold text-red-400 uppercase tracking-widest mb-2 flex items-center gap-2"><Skull size={14}/> Active Conflicts</h4>
           {ledger.activeConflicts.length === 0 ? <p className="text-gray-600 text-xs italic">Global peace (temporary).</p> : (
             <ul className="list-disc list-inside text-sm text-gray-300 space-y-1">
               {ledger.activeConflicts.map((s, i) => <li key={i}>{s}</li>)}
             </ul>
           )}
        </div>
        <div>
           <h4 className="text-xs font-bold text-yellow-400 uppercase tracking-widest mb-2 flex items-center gap-2"><Gavel size={14}/> Domestic Policy</h4>
           {ledger.domesticPolicies.length === 0 ? <p className="text-gray-600 text-xs italic">Standard governance.</p> : (
             <ul className="list-disc list-inside text-sm text-gray-300 space-y-1">
               {ledger.domesticPolicies.map((s, i) => <li key={i}>{s}</li>)}
             </ul>
           )}
        </div>
        <div>
           <h4 className="text-xs font-bold text-purple-400 uppercase tracking-widest mb-2 flex items-center gap-2"><User size={14}/> Key Figures</h4>
           {ledger.keyFigures.length === 0 ? <p className="text-gray-600 text-xs italic">No notable status changes.</p> : (
             <ul className="list-disc list-inside text-sm text-gray-300 space-y-1">
               {ledger.keyFigures.map((s, i) => <li key={i}>{s}</li>)}
             </ul>
           )}
        </div>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-200 font-serif">
      <StatBar stats={currentTurnData.stats} year={currentTurnData.year} />

      <div className="flex-grow overflow-y-auto scroll-smooth">
        <div className="max-w-4xl mx-auto p-4 md:p-8 pb-24 space-y-12">

          {history.map((entry, index) => {
            // Find the full TurnData related to this history entry. 
            // In a real refactor we should store the full TurnData in history, but for now we only have snapshots in the interface state if it's the current turn.
            // For past turns, we rely on the summary. For the *current* turn (last index), we render the full UI.
            const isCurrent = index === history.length - 1;

            return (
              <div 
                key={index} 
                ref={isCurrent ? lastTurnRef : null}
                className={`animate-fade-in ${isCurrent ? 'opacity-100' : 'opacity-60 grayscale hover:grayscale-0 hover:opacity-100 transition-all duration-500'}`}
              >
                <div className="flex items-center gap-4 mb-6 opacity-40">
                  <div className="h-px bg-gray-700 flex-grow"></div>
                  <span className="text-xs font-mono uppercase tracking-widest text-emerald-500">
                    {index === 0 ? 'Divergence Point' : `Turn ${entry.turnNumber}`}
                  </span>
                  <div className="h-px bg-gray-700 flex-grow"></div>
