                <div className="space-y-6">
                  <h2 className="text-3xl text-emerald-100 font-bold font-serif text-center mb-8">{entry.eventTitle}</h2>

                  {/* For the current turn, show the rich data. For past turns, we only have what we saved in history (which currently lacks the rich structure, so we just show narrative). */}
                  {isCurrent ? (
                    <>
