    // Public perception
    news: {
      type: Type.ARRAY,
      description: "3 distinct news headlines reflecting public perception or propaganda.",
      items: {
        type: Type.OBJECT,
        properties: {
          source: { type: Type.STRING, description: "Name of the publication or source (context appropriate)." },
          headline: { type: Type.STRING }
        },
        required: ["source", "headline"]
      }
    },

    // Intelligence Briefing
    narrative: { type: Type.STRING, description: "The classified situation report. What is REALLY happening? 100-150 words." },

    // Advisor System
    advisors: {
      type: Type.ARRAY,
      description: "2 Advisors with conflicting viewpoints on the current crisis.",
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          name: { type: Type.STRING },
          role: { type: Type.STRING, description: "Job title (e.g. 'General', 'Minister', 'Spy Master')" },
          advice: { type: Type.STRING, description: "First-person perspective advice urging a specific course of action." },
          bias: { type: Type.STRING, enum: ['aggressive', 'diplomatic', 'economic', 'scientific'] }
        },
        required: ["id", "name", "role", "advice", "bias"]
      }
    },

    stats: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER },
        wealth: { type: Type.INTEGER },
