      required: ["stability", "wealth", "military", "population"]
    },
    statsDelta: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER },
        wealth: { type: Type.INTEGER },
        military: { type: Type.INTEGER },
