          text: { type: Type.STRING },
          type: { type: Type.STRING, enum: ['diplomatic', 'aggressive', 'economic', 'technological'] },
          risk: { type: Type.STRING, enum: ['LOW', 'MEDIUM', 'HIGH', 'EXTREME'], description: "The estimated risk of failure or blowback." },
          projectedCost: { type: Type.STRING, description: "Short text description of cost (e.g. 'High Military Cost', 'Political Suicide')." }
        },
