// System instruction shared by both calls
const SYSTEM_INSTRUCTION = `
You are the "Chronus" Divergence Engine. You are a Grand Strategy Simulation AI.

YOUR NARRATIVE STYLE:
- Tone: Serious, high-stakes, geopolitical thriller.
- Detail: Use specific names of regiments, ships, cities, and politicians provided in the context.
- Causality: Brutal realism. If a player ignores a threat, it escalates. If they spend money they don't have, the economy crashes.

YOUR OUTPUTS:
1. **Intel Report (Narrative)**: Cold, objective, military-style briefing. No fluff. Focus on assets, movements, and political levers.
2. **Advisors**: They must have distinct personalities (e.g., a cynicism-filled Spy Master vs. an idealistic Reformer).
3. **News**: Headlines should often be wrong, sensationalist, or propaganda. They differ from the Intel Report.
4. **Choices**: Must be strategic trade-offs. "Do X (Cost Y)" or "Risk Z to gain W".
`;

// Helper function to hydrate short prompts into deep dossiers using AI knowledge
const enrichScenario = async (baseContext: string): Promise<string> => {
  const ai = getClient();

  // Detect if it's a raw custom prompt or a structured preset
  const isCustom = baseContext.startsWith("CUSTOM SCENARIO");
  const coreContent = isCustom 
    ? baseContext.replace("CUSTOM SCENARIO CREATED BY PLAYER. CONTEXT: ", "").split(". INSTRUCTIONS:")[0]
    : baseContext;

  const prompt = `
    ROLE: Historical Simulation Architect.

    INPUT SCENARIO SEED:
    "${coreContent}"

    OBJECTIVE:
    Transform this seed into a highly detailed "Classified Military Dossier" for a strategy game. 
    Use your internal historical knowledge to fill in missing gaps.

    REQUIREMENTS:
    1. **Specific Assets**: If the seed mentions "a fleet", you must name the flagship (e.g., "USS Saratoga"). If it mentions "an army", name the legion/division (e.g., "The Old Guard").
    2. **Real Historical Figures**: If the timeline allows, use real people as advisors/antagonists (e.g., "Talleyrand", "Curtis LeMay").
    3. **Economic Precision**: Invent plausible specific numbers (e.g., "Debt: £400 million").
    4. **Structure**: Keep the output organized (Timeline, Assets, Threats).

    If the input is already detailed (like a preset), refine and polish it to ensure maximum depth.
    If the input is a "What If" question (custom), build the entire world state around it.
  `;

  try {
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
    });
    return response.text || baseContext;
  } catch (e) {
    console.error("Scenario enrichment failed, falling back to raw seed", e);
    return baseContext;
  }
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();

  // 1. Expand the context (whether custom or preset) to ensure maximum depth.
  // This turns a 200-word seed into a 2000-word equivalent data structure.
  const fullDossier = await enrichScenario(scenarioContext);

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: INITIALIZE TIMELINE ===

    OFFICIAL ENRICHED DOSSIER:
    ${fullDossier}

    TASK:
    Construct Turn 1 based *strictly* on the Dossier above.
    - If the Dossier mentions specific Generals or Admirals, make them the Advisors.
    - If the Dossier mentions specific resource shortages (e.g. Grain, Coal), make that the central crisis.
    - Populate the "World Ledger" with the specific factions, military assets, and treaties mentioned.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Failed to init game:", error);
    throw error;
  }
};

export const consultAdvisor = async (
  advisor: Advisor,
  currentContext: string,
  userQuestion: string
): Promise<string> => {
  const ai = getClient();

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVISOR CONSULTATION ===

    CURRENT SITUATION REPORT:
    ${currentContext}

    YOUR PERSONA:
    Name: ${advisor.name}
    Role: ${advisor.role}
    Bias: ${advisor.bias}
    Your previous advice: "${advisor.advice}"

    USER QUESTION:
    "${userQuestion}"

    TASK:
    Answer the user's question directly.
    - Speak in first person ("I believe...", "My sources tell me...").
    - Maintain your bias and personality (e.g. if Aggressive, suggest force; if Economic, worry about cost).
    - Keep it brief (under 50 words).
    - Do NOT offer a "Quest". Just give your opinion.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash', // Use flash for fast chat interactions
      contents: prompt,
    });

    return response.text || "I have no comment on that matter, sir.";
  } catch (error) {
    console.error("Advisor consultation failed:", error);
    return "Comm-link disrupted. I cannot hear you.";
  }
};

export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  const fullHistoryLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Stats: S:${h.statsSnapshot.stability} W:${h.statsSnapshot.wealth} M:${h.statsSnapshot.military} P:${h.statsSnapshot.population}`
  ).join("\n");

  const latestState = currentHistory[currentHistory.length - 1];
  const currentLedger = latestState.ledgerSnapshot;

  const actionDescription = customInput 
    ? `Player input custom directive: "${customInput}"` 
    : `Player selected: "${playerChoiceText}"`;

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVANCE TIMELINE ===

    HISTORY LOG:
    ${fullHistoryLog}

    CURRENT WORLD LEDGER (Facts):
    ${JSON.stringify(currentLedger, null, 2)}

    PREVIOUS INTEL REPORT:
    Year: ${latestState.year}
    Briefing: ${latestState.narrative}

    PLAYER DECISION:
    ${actionDescription}

    TASK:
    1. **Calculate Consequences**: How does the Player's decision impact the specific factions and military assets in the Ledger?
    2. **Advance the World**: Did the enemy react? Did the economy fluctuate?
    3. **Update Ledger**: Add new conflicts, remove dead figures, update policies. Update Military Assets (remove destroyed units, add recruited ones).
    4. **Generate Turn Data**: Create the new Intel Report, News, Advisors, and Choices.

    CRITICAL: Reference specific names and events from the History Log to ensure continuity.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 4096 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

