import { GoogleGenAI, Type, Schema } from "@google/genai";
import { GameStats, TurnData, HistoryEntry, WorldLedger, Advisor } from '../types';

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY environment variable is not set.");
  }
  return new GoogleGenAI({ apiKey });
};

// Complex schema for the Situation Room experience
const turnSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    year: { type: Type.STRING },
    eventTitle: { type: Type.STRING },

    // Public perception
    news: {
      type: Type.ARRAY,
      description: "3 distinct news headlines reflecting public perception or propaganda.",
      items: {
        type: Type.OBJECT,
        properties: {
          source: { type: Type.STRING, description: "Name of the publication or source (context appropriate)." },
          headline: { type: Type.STRING }
        },
        required: ["source", "headline"]
      }
    },

    // Intelligence Briefing
    narrative: { type: Type.STRING, description: "The classified situation report. This must be a detailed, 3-paragraph dossier (approx 300 words). Paragraph 1: The immediate incident. Paragraph 2: The broader geopolitical reaction. Paragraph 3: The hidden threats or intelligence." },
    strategicOutlook: { type: Type.STRING, description: "A calculated forecast of the immediate future in percentage terms. e.g. 'Global War Probability: 85% | Regime Collapse: 15%'. Be specific to the scenario." },

    // Advisor System
    advisors: {
      type: Type.ARRAY,
      description: "2 Advisors with conflicting viewpoints on the current crisis.",
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          name: { type: Type.STRING },
          role: { type: Type.STRING, description: "Job title (e.g. 'General', 'Minister', 'Spy Master')" },
          advice: { type: Type.STRING, description: "First-person perspective advice urging a specific course of action." },
          bias: { type: Type.STRING, enum: ['aggressive', 'diplomatic', 'economic', 'scientific'] }
        },
        required: ["id", "name", "role", "advice", "bias"]
      }
    },

    stats: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER },
        wealth: { type: Type.INTEGER },
        military: { type: Type.INTEGER },
        population: { type: Type.INTEGER, description: "Either a raw number (e.g. 1000000) OR a support percentage (0-100). Be consistent." },
      },
      required: ["stability", "wealth", "military", "population"]
    },
    statsDelta: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER },
        wealth: { type: Type.INTEGER },
        military: { type: Type.INTEGER },
        population: { type: Type.INTEGER },
      },
      required: ["stability", "wealth", "military", "population"]
    },
    statsReasoning: { type: Type.STRING, description: "A concise 1-2 sentence explanation of EXACTLY why stats changed. e.g., 'Military spending drained Wealth, but troops stabilized the region.'" },
    ledger: {
      type: Type.OBJECT,
      properties: {
        diplomaticStatus: { type: Type.ARRAY, items: { type: Type.STRING } },
        activeConflicts: { type: Type.ARRAY, items: { type: Type.STRING } },
        domesticPolicies: { type: Type.ARRAY, items: { type: Type.STRING } },
        keyFigures: { type: Type.ARRAY, items: { type: Type.STRING } },
        militaryAssets: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Specific named military units, fleets, or super-weapons available to the player." }
      },
      required: ["diplomaticStatus", "activeConflicts", "domesticPolicies", "keyFigures", "militaryAssets"]
    },
    choices: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          text: { type: Type.STRING, description: "The main action title." },
          type: { type: Type.STRING, enum: ['diplomatic', 'aggressive', 'economic', 'technological'] },
          risk: { type: Type.STRING, enum: ['LOW', 'MEDIUM', 'HIGH', 'EXTREME'], description: "The estimated risk of failure or blowback." },
          projectedCost: { type: Type.STRING, description: "Short text description of cost (e.g. 'High Military Cost', 'Political Suicide')." },
          detailedDescription: { type: Type.STRING, description: "A 2-3 sentence strategic analysis of what this choice entails." },
          outcomeProbability: { type: Type.STRING, description: "Estimated success rate ranges. e.g. 'Mission Success: 75%, Catastrophic Failure: 15%'" }
        },
