                             {currentTurnData.advisors.map((adv) => (
                               <AdvisorCard key={adv.id} advisor={adv} context={currentTurnData.narrative} />
                             ))}
                          </div>
                       </div>
                    </>
                  ) : (
                    // Past turns view (simplified)
                    <div className="prose prose-invert prose-lg max-w-none text-gray-400">
                        <p className="whitespace-pre-wrap">{entry.narrative}</p>
                        {entry.strategicOutlook && (
                           <div className="mt-2 text-xs font-mono text-gray-500 border-l border-gray-700 pl-2">
                              Forecast at the time: {entry.strategicOutlook}
                           </div>
                        )}
