                    >
                        {showLedger ? 'Hide Intel' : 'View World Intel'}
                    </button>
                 </div>

                 {showLedger && <LedgerPanel ledger={currentTurnData.ledger} />}

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                    {currentTurnData.choices.map(renderChoiceButton)}
                 </div>

                 <div className="relative group">
                    <div className="absolute -inset-0.5 bg-gradient-to-r from-emerald-900 to-blue-900 rounded-lg blur opacity-20 group-hover:opacity-40 transition duration-1000"></div>
                    <div className="relative flex items-end bg-gray-950 rounded-lg border border-gray-700 shadow-inner">
                        <textarea
                            ref={textareaRef}
                            value={customInput}
                            onChange={(e) => setCustomInput(e.target.value)}
                            placeholder="Overwrite protocol with custom directive..."
                            rows={1}
                            className="w-full bg-transparent border-none rounded-lg pl-5 pr-14 py-4 focus:ring-0 text-base font-mono resize-none overflow-hidden"
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && !e.shiftKey) {
                                    e.preventDefault();
                                    if(customInput) handleTurn(customInput, null, true);
                                }
                            }}
                        />
                        <button 
                            onClick={() => customInput && handleTurn(customInput, null, true)}
                            disabled={!customInput}
                            className="absolute right-3 bottom-3 p-2 bg-emerald-900/20 text-emerald-500 hover:bg-emerald-800 hover:text-emerald-100 rounded-md transition-all disabled:opacity-0 disabled:pointer-events-none"
                        >
                            <Send size={20} />
                        </button>
                    </div>
                 </div>
             </div>
          )}

          {currentTurnData.gameOver && !loading && (
             <div className="bg-gray-800 border border-yellow-700/50 p-8 rounded-xl text-center shadow-2xl mt-12">
