const SYSTEM_INSTRUCTION = `
You are the "Chronus" Universal Divergence Engine. You are a Grand Strategy Simulation AI.

YOUR NARRATIVE STYLE:
- Tone: Serious, high-stakes.
- Detail: Use specific names of assets, people, and organizations.
- Causality: Brutal realism.

YOUR CORE MECHANIC:
You must first determine the **CONTEXT** of the simulation based on the scenario.
1. **Military Context**: Dynamic Stat = "Readiness" or "Firepower". Ledger = Armies, Enemies. Choice Types = Force vs Diplomacy.
2. **Corporate Context**: Dynamic Stat = "Innovation" or "Market Share". Ledger = Patents, Competitors. Choice Types = Profit vs Innovation.
3. **Political Context**: Dynamic Stat = "Influence" or "Votes". Ledger = Donors, Opponents. Choice Types = Diplomacy vs Force (Slander).
4. **Crisis Context**: Dynamic Stat = "Infection Rate" or "Power Grid". Ledger = Hospitals, Outbreaks.

YOUR OUTPUTS:
1. **Intel Report**: Cold, objective briefing.
2. **Advisors**: Distinct personalities fitting the context.
3. **News**: Headlines reflecting public perception.
4. **Stats**: Maintain consistency. "Support" is generic (Voters/Shareholders/Population).
`;

const enrichScenario = async (baseContext: string): Promise<string> => {
  const ai = getClient();

  const isCustom = baseContext.startsWith("CUSTOM SCENARIO");
  const coreContent = isCustom 
    ? baseContext.replace("CUSTOM SCENARIO CREATED BY PLAYER. CONTEXT: ", "").split(". INSTRUCTIONS:")[0]
    : baseContext;

  const prompt = `
    ROLE: Simulation Architect.

    INPUT SCENARIO SEED:
    "${coreContent}"

    OBJECTIVE:
    Transform this seed into a highly detailed "Classified Dossier" for a strategy game.
    Determine if this is a WAR, a BUSINESS SIMULATION, a POLITICAL CAMPAIGN, or a SURVIVAL SCENARIO.

    REQUIREMENTS:
    1. **Specific Assets**: Invent specific names (e.g. "USS Saratoga" for war, "Project X-1" for business).
    2. **Real Historical Figures**: Use real people if possible.
    3. **Numbers**: plausible specific numbers.
    4. **Structure**: Timeline, Key Assets, Active Threats.
  `;

  try {
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
    });
    return response.text || baseContext;
  } catch (e) {
    console.error("Scenario enrichment failed, falling back to raw seed", e);
    return baseContext;
  }
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();
  const fullDossier = await enrichScenario(scenarioContext);

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: INITIALIZE TIMELINE ===

    OFFICIAL ENRICHED DOSSIER:
    ${fullDossier}

    TASK:
    Construct Turn 1 based strictly on the Dossier.
    - DEFINE the "Primary Dynamic Stat" based on the scenario type (e.g. "Military", "Innovation", "Infection Rate").
    - Populate the "World Ledger" using generic keys (External Relations, Active Threats, Key Assets) adapted to the specific context.
    - GENERATE A DETAILED 3-PARAGRAPH NARRATIVE REPORT.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Failed to init game:", error);
    throw error;
  }
};

export const consultAdvisor = async (
  advisor: any, // Typed loosely here as we pass the whole object
  currentContext: string,
  userQuestion: string
): Promise<string> => {
  const ai = getClient();

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVISOR CONSULTATION ===

    CURRENT REPORT:
    ${currentContext}

    YOUR PERSONA:
    Name: ${advisor.name}
    Role: ${advisor.role}
    Bias: ${advisor.bias}
    Your previous advice: "${advisor.advice}"

    USER QUESTION:
    "${userQuestion}"

    TASK:
    Answer the user's question directly in character. Keep it brief.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "I have no comment.";
  } catch (error) {
    return "Comm-link disrupted.";
  }
};

export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  choiceDetails: string | null,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  const fullHistoryLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Stats: S:${h.statsSnapshot.stability} W:${h.statsSnapshot.wealth} Support:${h.statsSnapshot.support} ${h.statsSnapshot.primaryStatLabel}:${h.statsSnapshot.primaryStatValue}`
  ).join("\n");

  const latestState = currentHistory[currentHistory.length - 1];
  const currentLedger = latestState.ledgerSnapshot;

  let actionDescription = "";
  if (customInput) {
    actionDescription = `Player input custom directive: "${customInput}"`;
  } else {
    actionDescription = `Player selected: "${playerChoiceText}".`;
    if (choiceDetails) {
        actionDescription += `\n\n=== EXECUTION DETAILS ===\n${choiceDetails}\n=========================================`;
    }
  }

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVANCE TIMELINE ===

    HISTORY LOG:
    ${fullHistoryLog}

    CURRENT WORLD LEDGER (Facts):
    ${JSON.stringify(currentLedger, null, 2)}

    PREVIOUS INTEL REPORT:
    Year: ${latestState.year}
    Briefing: ${latestState.narrative}

    PLAYER DECISION:
    ${actionDescription}

    TASK:
    1. **Calculate Consequences**: Impact on Ledger factions and Assets.
    2. **Advance the World**: Reaction from enemies/competitors.
    3. **Update Ledger**: Update Threats, Relations, Assets.
    4. **Generate Turn Data**: Intel Report, News, Advisors, Choices.

    CRITICAL: Maintain the "Primary Dynamic Stat" label used in previous turns (${latestState.statsSnapshot.primaryStatLabel}).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

