import { GoogleGenAI, Type, Schema } from "@google/genai";
import { TurnData, HistoryEntry } from '../types';

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY environment variable is not set.");
  }
  return new GoogleGenAI({ apiKey });
};

// Generic schema for the Universal Simulation Engine
const turnSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    year: { type: Type.STRING },
    eventTitle: { type: Type.STRING },

    news: {
      type: Type.ARRAY,
      description: "3 distinct news headlines reflecting public perception.",
      items: {
        type: Type.OBJECT,
        properties: {
          source: { type: Type.STRING, description: "Name of the publication or source." },
          headline: { type: Type.STRING }
        },
        required: ["source", "headline"]
      }
    },

    narrative: { type: Type.STRING, description: "The classified situation report. A detailed, 3-paragraph dossier (approx 300 words). Paragraph 1: Immediate incident. Paragraph 2: Broader reaction. Paragraph 3: Hidden threats or opportunities." },

    advisors: {
      type: Type.ARRAY,
      description: "2 Advisors with conflicting viewpoints.",
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          name: { type: Type.STRING },
          role: { type: Type.STRING },
          advice: { type: Type.STRING, description: "First-person perspective advice." },
          bias: { type: Type.STRING, enum: ['force', 'diplomacy', 'profit', 'innovation'] }
        },
        required: ["id", "name", "role", "advice", "bias"]
      }
    },

    stats: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER, description: "Internal cohesion/loyalty (0-100)." },
        wealth: { type: Type.INTEGER, description: "Resources/Money/Budget (0-100)." },
        support: { type: Type.INTEGER, description: "External validation/Popularity/Shareholder Trust (0-100)." },
        primaryStatLabel: { type: Type.STRING, description: "The name of the dynamic 4th stat (e.g. 'Military Readiness', 'Innovation', 'Infection Rate')." },
        primaryStatValue: { type: Type.INTEGER, description: "Value of the dynamic stat (0-100)." },
      },
      required: ["stability", "wealth", "support", "primaryStatLabel", "primaryStatValue"]
    },
    statsDelta: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER },
        wealth: { type: Type.INTEGER },
        support: { type: Type.INTEGER },
        primaryStatValue: { type: Type.INTEGER },
      },
      required: ["stability", "wealth", "support", "primaryStatValue"]
    },
    statsReasoning: { type: Type.STRING, description: "1-2 sentence explanation of why stats changed." },

    ledger: {
      type: Type.OBJECT,
      properties: {
        externalRelations: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Allies, Partners, or Treaties." },
        activeThreats: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Wars, Lawsuits, Competitors, or Disasters." },
        internalPolicies: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Laws, Corporate Strategies, or Social Reforms." },
        keyFigures: { type: Type.ARRAY, items: { type: Type.STRING } },
        keyAssets: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Specific named assets (Armies, Tech Labs, Patents, Fleets)." }
      },
      required: ["externalRelations", "activeThreats", "internalPolicies", "keyFigures", "keyAssets"]
    },

    choices: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          text: { type: Type.STRING, description: "The action title." },
          type: { type: Type.STRING, enum: ['diplomacy', 'force', 'profit', 'innovation'] },
          risk: { type: Type.STRING, enum: ['LOW', 'MEDIUM', 'HIGH', 'EXTREME'] },
          projectedCost: { type: Type.STRING },
          detailedDescription: { type: Type.STRING, description: "3-4 sentence strategic analysis of immediate effects." },
          outcomeProbability: { type: Type.STRING },
          technicalReport: { type: Type.STRING, description: "2-3 paragraph operational report on execution details." }
        },
        required: ["id", "text", "type", "risk", "detailedDescription", "outcomeProbability", "technicalReport"]
      }
    },
    gameOver: { type: Type.BOOLEAN }
  },
  required: ["year", "eventTitle", "news", "narrative", "advisors", "stats", "statsDelta", "statsReasoning", "ledger", "choices", "gameOver"]
};

const SYSTEM_INSTRUCTION = `
You are the "Chronus" Universal Divergence Engine. You are a Grand Strategy Simulation AI.

YOUR CORE MECHANIC:
You must first determine the **CONTEXT** of the simulation based on the scenario.
1. **Military Context**: Dynamic Stat = "Readiness" or "Firepower". Ledger = Armies, Enemies. Choice Types = Force vs Diplomacy.
2. **Corporate Context**: Dynamic Stat = "Innovation" or "Market Share". Ledger = Patents, Competitors. Choice Types = Profit vs Innovation.
3. **Political Context**: Dynamic Stat = "Influence" or "Votes". Ledger = Donors, Opponents. Choice Types = Diplomacy vs Force (Slander).
4. **Crisis Context**: Dynamic Stat = "Infection Rate" or "Power Grid". Ledger = Hospitals, Outbreaks.

=== ADJUDICATION PROTOCOL ===
Do not act as a "Yes, And" improviser. Act as a harsh Game Master.
When the player makes a choice, you MUST evaluate two factors:

1. **FEASIBILITY (The Stat Check)**
   - Does the player have the resources (Wealth, Support) to execute this?
   - If Wealth is LOW (under 30) and they try to bribe someone, they MUST FAIL.

2. **NOVELTY (Obvious vs. Creative)**
   - **Obvious/Conventional**: Standard political/military moves.
     - *Pros*: Reliable if stats are high.
     - *Cons*: Predictable. Enemies might anticipate it. Low reward ceiling.
   - **Unorthodox/Creative**: Weird, risky, or "out of the box" moves.
     - *Pros*: Can bypass defenses. High reward ceiling.
     - *Cons*: High unintended consequences.

=== OUTCOME ARCHETYPES ===
Based on the intersection of Feasibility and Novelty, choose an outcome:

A. **Standard Execution** (Obvious + Feasible):
   - Result: Success. Stats improve moderately.
   - Narrative: "You did the expected thing. It worked, but changed little."

B. **Predictable Failure** (Obvious + Infeasible):
   - Result: Failure. Stats drop.
   - Narrative: "You tried the standard playbook, but lacked the resources. You were laughed out of the room."

C. **The Breakthrough** (Creative + Feasible):
   - Result: Great Success + Unintended Consequence.
   - Narrative: "It was a gamble. It paid off huge. However, this success has created a new, strange problem..."

D. **The Nugget** (Creative + Infeasible):
   - Result: Tragic Failure with a Silver Lining.
   - Narrative: "The plan collapsed. You lost resources. BUT, amidst the chaos, you discovered a secret or gained a loyal asset."

YOUR NARRATIVE STYLE:
- Tone: Serious, high-stakes.
- Detail: Use specific names of assets, people, and organizations.
- Causality: Brutal realism.
`;

const enrichScenario = async (baseContext: string): Promise<string> => {
  const ai = getClient();

  const isCustom = baseContext.startsWith("CUSTOM SCENARIO");
  const coreContent = isCustom 
    ? baseContext.replace("CUSTOM SCENARIO CREATED BY PLAYER. CONTEXT: ", "").split(". INSTRUCTIONS:")[0]
    : baseContext;

  const prompt = `
    ROLE: Simulation Architect.

    INPUT SCENARIO SEED:
    "${coreContent}"

    OBJECTIVE:
    Transform this seed into a highly detailed "Classified Dossier" for a strategy game.
    Determine if this is a WAR, a BUSINESS SIMULATION, a POLITICAL CAMPAIGN, or a SURVIVAL SCENARIO.

    REQUIREMENTS:
    1. **Specific Assets**: Invent specific names (e.g. "USS Saratoga" for war, "Project X-1" for business).
    2. **Real Historical Figures**: Use real people if possible.
    3. **Numbers**: plausible specific numbers.
    4. **Structure**: Timeline, Key Assets, Active Threats.
  `;

  try {
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
    });
    return response.text || baseContext;
  } catch (e) {
    console.error("Scenario enrichment failed, falling back to raw seed", e);
    return baseContext;
  }
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();
  const fullDossier = await enrichScenario(scenarioContext);

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: INITIALIZE TIMELINE ===

    OFFICIAL ENRICHED DOSSIER:
    ${fullDossier}

    TASK:
    Construct Turn 1 based strictly on the Dossier.
    - DEFINE the "Primary Dynamic Stat" based on the scenario type (e.g. "Military", "Innovation", "Infection Rate").
    - Populate the "World Ledger" using generic keys (External Relations, Active Threats, Key Assets) adapted to the specific context.
    - GENERATE A DETAILED 3-PARAGRAPH NARRATIVE REPORT.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Failed to init game:", error);
    throw error;
  }
};

export const consultAdvisor = async (
  advisor: any, // Typed loosely here as we pass the whole object
  currentContext: string,
  userQuestion: string
): Promise<string> => {
  const ai = getClient();

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVISOR CONSULTATION ===

    CURRENT REPORT:
    ${currentContext}

    YOUR PERSONA:
    Name: ${advisor.name}
    Role: ${advisor.role}
    Bias: ${advisor.bias}
    Your previous advice: "${advisor.advice}"

    USER QUESTION:
    "${userQuestion}"

    TASK:
    Answer the user's question directly in character. Keep it brief.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "I have no comment.";
  } catch (error) {
    return "Comm-link disrupted.";
  }
};

export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  choiceDetails: string | null,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  const fullHistoryLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Stats: S:${h.statsSnapshot.stability} W:${h.statsSnapshot.wealth} Support:${h.statsSnapshot.support} ${h.statsSnapshot.primaryStatLabel}:${h.statsSnapshot.primaryStatValue}`
  ).join("\n");

  const latestState = currentHistory[currentHistory.length - 1];
  const currentLedger = latestState.ledgerSnapshot;

  let actionDescription = "";
  if (customInput) {
    actionDescription = `Player input custom directive: "${customInput}"`;
  } else {
    actionDescription = `Player selected: "${playerChoiceText}".`;
    if (choiceDetails) {
        actionDescription += `\n\n=== EXECUTION DETAILS ===\n${choiceDetails}\n=========================================`;
    }
  }

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVANCE TIMELINE ===

    HISTORY LOG:
    ${fullHistoryLog}

    CURRENT WORLD LEDGER (Facts):
    ${JSON.stringify(currentLedger, null, 2)}

    PREVIOUS INTEL REPORT:
    Year: ${latestState.year}
    Briefing: ${latestState.narrative}

    PLAYER DECISION:
    ${actionDescription}

    TASK:
    1. **ADJUDICATE**: 
       - Is this decision Obvious or Novel?
       - Are the stats sufficient?
       - Select the Outcome Archetype (Standard, Predictable Failure, Breakthrough, or The Nugget).
    2. **CALCULATE**: Impact on Ledger factions and Assets.
    3. **NARRATE**: Generate the outcome, respecting the chosen archetype.
       - If "Breakthrough": Ensure there is an unintended consequence.
       - If "Predictable Failure": Ensure it is punishing.
    4. **UPDATE**: Generate Turn Data (Intel, News, Advisors).

    CRITICAL: Maintain the "Primary Dynamic Stat" label used in previous turns (${latestState.statsSnapshot.primaryStatLabel}).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

