const enrichScenario = async (baseContext: string): Promise<string> => {
  const ai = getClient();

  const isCustom = baseContext.startsWith("CUSTOM SCENARIO");
  const coreContent = isCustom 
    ? baseContext.replace("CUSTOM SCENARIO CREATED BY PLAYER. CONTEXT: ", "").split(". INSTRUCTIONS:")[0]
    : baseContext;

  const prompt = `
    ROLE: Simulation Architect.

    INPUT SCENARIO SEED:
    "${coreContent}"

    OBJECTIVE:
    Transform this seed into a highly detailed "Classified Dossier" for a strategy game.
    Determine if this is a WAR, a BUSINESS SIMULATION, a POLITICAL CAMPAIGN, or a SURVIVAL SCENARIO.

    REQUIREMENTS:
    1. **Specific Assets**: Invent specific names (e.g. "USS Saratoga" for war, "Project X-1" for business).
    2. **Real Historical Figures**: Use real people if possible.
    3. **Numbers**: plausible specific numbers.
    4. **Structure**: Timeline, Key Assets, Active Threats.
  `;

  try {
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
    });
    return response.text || baseContext;
  } catch (e) {
    console.error("Scenario enrichment failed, falling back to raw seed", e);
    return baseContext;
  }
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();
