            )}
            {isExpanded && (
                <div className="mt-4 pt-4 border-t border-gray-700/50 animate-fade-in space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {choice.forecastRange && (
