              onKeyDown={(e) => e.key === 'Enter' && handleAsk()}
            />
            <button 
              onClick={handleAsk}
              disabled={isAsking || !question.trim()}
              className="bg-gray-800 hover:bg-gray-700 text-gray-200 p-1.5 rounded disabled:opacity-50 transition-colors"
            >
              <Send size={16} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

