const SYSTEM_INSTRUCTION = `
You are the "Chronus" Universal Divergence Engine. You are a Grand Strategy Simulation AI.

=== CORE MECHANIC: CONTEXT ===
Determine the context of the scenario:
1. **Military Context**: Dynamic Stat = "Readiness". Ledger = Armies, Enemies.
2. **Corporate Context**: Dynamic Stat = "Market Share". Ledger = Patents, Competitors.
3. **Political Context**: Dynamic Stat = "Democratic Integrity" or "Influence". Ledger = Donors, Opponents.
4. **Crisis Context**: Dynamic Stat = "Infection Rate". Ledger = Hospitals, Outbreaks.

=== THE ADJUDICATION MATRIX (INTERNAL LOGIC) ===
Use these rules to decide outcomes.
1. [CONVENTIONAL + FEASIBLE] => "The Grind" -> Plain Label: "Strategic Success" or "Operational Success"
2. [CONVENTIONAL + INFEASIBLE] => "The Wall" -> Plain Label: "Operational Failure" or "Stalemate"
3. [CREATIVE + FEASIBLE] => "The Monkey's Paw" -> Plain Label: "Pyrrhic Victory" or "Partial Success (High Cost)"
4. [CREATIVE + INFEASIBLE] => "The Silver Lining" -> Plain Label: "Mitigated Disaster" or "Unintended Benefit"

=== OBSCURITY PROTOCOL (CRITICAL) ===
You must maintain the illusion of a realistic simulation.
**DO NOT** use the terms "Monkey's Paw", "Silver Lining", "Grind", or "Wall" in the narrative, detailed descriptions, OR outcome labels.
Instead, describe the specific in-universe consequences.

=== CHOICE GENERATION PROTOCOL ===
You must generate exactly 4 strategic choices. They MUST be diverse:
1. **Option 1 (The Safe Bet)**: Low Risk. Conventional. Focus on Diplomacy or Econ.
2. **Option 2 (Hard Power)**: Medium Risk. Conventional. Focus on Force or Aggression.
3. **Option 3 (The Wildcard)**: High Risk. Creative/Unorthodox.
4. **Option 4 (The Desperate Measure)**: Extreme Risk. Creative/Unorthodox.

=== FOG OF WAR PROTOCOL ===
When defining \`forecastConfidence\`:
- **HIGH**: Standard, well-understood moves. You (the Engine) must honor the \`forecastRange\` if the player picks this.
- **VOLATILE / LOW**: Experimental, chaotic, or secretive moves. If the player picks this, the outcome MUST contain unexpected twists regardless of stats.

=== NARRATIVE STYLE ===
- Tone: Serious, high-stakes.
- Detail: Use specific names of assets, people, and organizations.
- Causality: Brutal realism.
`;

const enrichScenario = async (baseContext: string): Promise<string> => {
  const ai = getClient();

  const isCustom = baseContext.startsWith("CUSTOM SCENARIO");
  const coreContent = isCustom 
    ? baseContext.replace("CUSTOM SCENARIO CREATED BY PLAYER. CONTEXT: ", "").split(". INSTRUCTIONS:")[0]
    : baseContext;

  const prompt = `
    ROLE: Simulation Architect.

    INPUT SCENARIO SEED:
    "${coreContent}"

    OBJECTIVE:
    Transform this seed into a highly detailed "Classified Dossier" for a strategy game.
    Determine if this is a WAR, a BUSINESS SIMULATION, a POLITICAL CAMPAIGN, or a SURVIVAL SCENARIO.

    REQUIREMENTS:
    1. **Specific Assets**: Invent specific names (e.g. "USS Saratoga" for war, "Project X-1" for business).
    2. **Real Historical Figures**: Use real people if possible.
    3. **Numbers**: plausible specific numbers.
    4. **Structure**: Timeline, Key Assets, Active Threats.
  `;

  try {
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
    });
    return response.text || baseContext;
  } catch (e) {
    console.error("Scenario enrichment failed, falling back to raw seed", e);
    return baseContext;
  }
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();
  const fullDossier = await enrichScenario(scenarioContext);

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: INITIALIZE TIMELINE ===

    OFFICIAL ENRICHED DOSSIER:
    ${fullDossier}

    TASK:
    Construct Turn 1 based strictly on the Dossier.
    - DEFINE the "Primary Dynamic Stat" based on the scenario type.
    - Populate the "World Ledger" using generic keys.
    - GENERATE A DETAILED 3-PARAGRAPH NARRATIVE REPORT.
    - **Execution Analysis**: Since this is Turn 1, set 'outcomeLabel' to 'Timeline Initialization' and 'directiveType' to 'STANDARD'.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Failed to init game:", error);
    throw error;
  }
};

export const consultAdvisor = async (
  advisor: any, // Typed loosely here as we pass the whole object
  currentContext: string,
  userQuestion: string
): Promise<string> => {
  const ai = getClient();

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVISOR CONSULTATION ===

    CURRENT REPORT:
    ${currentContext}

    YOUR PERSONA:
    Name: ${advisor.name}
    Role: ${advisor.role}
    Bias: ${advisor.bias}
    Your previous advice: "${advisor.advice}"

    USER QUESTION:
    "${userQuestion}"

    TASK:
    Answer the user's question directly in character. Keep it brief.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "I have no comment.";
  } catch (error) {
    return "Comm-link disrupted.";
  }
};

export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  choiceDetails: string | null,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  const fullHistoryLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Stats: S:${h.statsSnapshot.stability} W:${h.statsSnapshot.wealth} Support:${h.statsSnapshot.support} ${h.statsSnapshot.primaryStatLabel}:${h.statsSnapshot.primaryStatValue}`
  ).join("\n");

  const latestState = currentHistory[currentHistory.length - 1];
  const currentLedger = latestState.ledgerSnapshot;

  let actionDescription = "";
  if (customInput) {
    actionDescription = `Player input custom directive: "${customInput}"`;
  } else {
    actionDescription = `Player selected: "${playerChoiceText}".`;
    if (choiceDetails) {
        actionDescription += `\n\n=== EXECUTION DETAILS ===\n${choiceDetails}\n=========================================`;
    }
  }

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVANCE TIMELINE ===

    HISTORY LOG:
    ${fullHistoryLog}

    CURRENT WORLD LEDGER (Facts):
    ${JSON.stringify(currentLedger, null, 2)}

    PREVIOUS INTEL REPORT:
    Year: ${latestState.year}
    Briefing: ${latestState.narrative}

    PLAYER DECISION:
    ${actionDescription}

    TASK:
    1. **ADJUDICATE**: 
       - Look at the player's choice. Did the previous turn's forecast indicate HIGH confidence or LOW/VOLATILE confidence?
       - **If Confidence was LOW/VOLATILE**: You MUST introduce a twist, unintended consequence, or wild variance in the outcome (Monkey's Paw/Silver Lining), regardless of stats.
       - **If Confidence was HIGH**: Stick to the standard Adjudication Matrix based on stats.
    2. **CALCULATE**: Apply the specific Outcome Rules.
    3. **NARRATE**: 
       - If "Monkey's Paw": Narrate the success, then reveal the curse.
       - If "Silver Lining": Narrate the disaster, then reveal the prize.
    4. **AUTOPSY (Execution Analysis)**:
       - Populate the \`executionAnalysis\` object for the move just taken.
       - If it was a CUSTOM input, assign it a Risk, Forecast Range, and Confidence retroactively based on how ambitious it was.
       - **Crucially**: Set \`outcomeLabel\` to a plain language summary (e.g. "Pyrrhic Victory", "Costly Success") that corresponds to the Adjudication Matrix result.
       - **STRICT PROHIBITION**: Do NOT include the internal terms (e.g. "(The Monkey's Paw)") in the \`outcomeLabel\`. Only use the plain language description.
    5. **UPDATE**: Generate Turn Data (Intel, News, Advisors).
       - **CRITICAL**: GENERATE 4 NEW DIVERSE CHOICES for the next turn.

    CRITICAL: Maintain the "Primary Dynamic Stat" label used in previous turns (${latestState.statsSnapshot.primaryStatLabel}).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

