        keyAssets: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Specific named assets (Armies, Tech Labs, Patents, Fleets)." }
      },
      required: ["externalRelations", "activeThreats", "internalPolicies", "keyFigures", "keyAssets"]
    },

    choices: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          text: { type: Type.STRING, description: "The action title." },
          type: { type: Type.STRING, enum: ['diplomacy', 'force', 'profit', 'innovation'] },
          risk: { type: Type.STRING, enum: ['LOW', 'MEDIUM', 'HIGH', 'EXTREME'] },
          projectedCost: { type: Type.STRING },
          detailedDescription: { type: Type.STRING, description: "3-4 sentence strategic analysis of immediate effects." },
          forecastRange: { type: Type.STRING, description: "Estimated success rate (e.g., '30-50%', 'Low-Medium')." },
          forecastConfidence: { type: Type.STRING, enum: ['HIGH', 'MEDIUM', 'LOW', 'VOLATILE'], description: "Reliability of the intel." },
          technicalReport: { type: Type.STRING, description: "2-3 paragraph operational report on execution details. MUST be in-universe." }
        },
        required: ["id", "text", "type", "risk", "detailedDescription", "forecastRange", "forecastConfidence", "technicalReport"]
      }
    },

    executionAnalysis: {
        type: Type.OBJECT,
        description: "Post-action analysis of the move that was JUST taken.",
        properties: {
            directiveType: { type: Type.STRING, enum: ['STANDARD', 'CUSTOM'] },
            perceivedRisk: { type: Type.STRING, enum: ['LOW', 'MEDIUM', 'HIGH', 'EXTREME'] },
            forecastedRange: { type: Type.STRING },
            forecastConfidence: { type: Type.STRING, enum: ['HIGH', 'MEDIUM', 'LOW', 'VOLATILE'] },
            outcomeCategory: { type: Type.STRING, enum: ['VICTORY', 'PARTIAL_SUCCESS', 'PARTIAL_FAILURE', 'CRITICAL_FAILURE'], description: "The internal classification of the result." },
            outcomeLabel: { type: Type.STRING, description: "Plain language description of the result (e.g., 'Strategic Success', 'Pyrrhic Victory', 'Total Failure'). DO NOT include internal codenames." },
            resourcesConsumed: { type: Type.STRING, description: "Summary of cost." }
        },
        required: ["directiveType", "perceivedRisk", "forecastedRange", "forecastConfidence", "outcomeCategory", "outcomeLabel", "resourcesConsumed"]
    },

    gameOver: { type: Type.BOOLEAN }
  },
  required: ["year", "eventTitle", "news", "narrative", "advisors", "stats", "statsDelta", "statsReasoning", "ledger", "choices", "gameOver", "executionAnalysis"]
};

const SYSTEM_INSTRUCTION = `
You are the "Chronus" Universal Divergence Engine. You are a Grand Strategy Simulation AI.

=== CORE MECHANIC: CONTEXT ===
Determine the context of the scenario:
1. **Military Context**: Dynamic Stat = "Readiness". Ledger = Armies, Enemies.
2. **Corporate Context**: Dynamic Stat = "Market Share". Ledger = Patents, Competitors.
3. **Political Context**: Dynamic Stat = "Democratic Integrity" or "Influence". Ledger = Donors, Opponents.
4. **Crisis Context**: Dynamic Stat = "Infection Rate". Ledger = Hospitals, Outbreaks.

=== THE ADJUDICATION MATRIX (OUTCOME LOGIC) ===
Classify all results into exactly one of these 4 categories.

1. **VICTORY** (Green): Objective achieved fully. No significant downsides.
   - *Logic*: Use this for High Confidence + Good Stats/Feasible Plans.
   - *Scaling*:
     - Low Risk move -> "Operational Success" (Small gain).
     - High Risk move -> "Decisive Triumph" (Massive gain).

2. **PARTIAL SUCCESS** (Light Green): Objective achieved, but with a cost.
   - *Logic*: SUCCESS > DOWNSIDE. The player got what they wanted, but it hurt.
   - *Use Case*: High Difficulty or "The Grind".
   - *Labels*: "Costly Success", "Pyrrhic Victory", "Strategic Trade-off".

3. **PARTIAL FAILURE** (Light Red): Objective failed, but with an upside.
   - *Logic*: FAILURE > UPSIDE. The player failed, but there is a silver lining.
   - *Use Case*: Creative but impossible ideas.
   - *Labels*: "Mitigated Defeat", "Stalemate", "Moral Victory".

4. **CRITICAL FAILURE** (Red): Objective failed completely. Resources lost.
   - *Logic*: Pure loss. Do not cushion the blow.
   - *Scaling*:
     - Low Risk move -> "Operational Setback" (Annoying loss).
     - High Risk move -> "Catastrophic Collapse" (Game-altering loss).

=== OBSCURITY PROTOCOL (CRITICAL) ===
You must maintain the illusion of a realistic simulation.
**DO NOT** use the terms "Partial Success" or "Critical Failure" in the \`outcomeLabel\`.
Use immersive, descriptive terms like "Strategic Success", "Costly Advance", "Total Debacle".

=== CHOICE GENERATION PROTOCOL ===
You must generate exactly 4 strategic choices. They MUST be diverse:
1. **Option 1 (The Safe Bet)**: Low Risk. Conventional. Focus on Diplomacy or Econ.
2. **Option 2 (Hard Power)**: Medium Risk. Conventional. Focus on Force or Aggression.
3. **Option 3 (The Wildcard)**: High Risk. Creative/Unorthodox.
4. **Option 4 (The Desperate Measure)**: Extreme Risk. Creative/Unorthodox.

=== FOG OF WAR PROTOCOL ===
When defining \`forecastConfidence\`:
- **HIGH**: Standard, well-understood moves.
- **VOLATILE / LOW**: Experimental, chaotic, or secretive moves.
- **Rule**: If Confidence was LOW/VOLATILE, you MUST introduce a twist (Positive or Negative) regardless of stats.

=== NARRATIVE STYLE ===
- Tone: Serious, high-stakes.
- Detail: Use specific names of assets, people, and organizations.
- Causality: Brutal realism.
`;

const enrichScenario = async (baseContext: string): Promise<string> => {
  const ai = getClient();

  const isCustom = baseContext.startsWith("CUSTOM SCENARIO");
  const coreContent = isCustom 
    ? baseContext.replace("CUSTOM SCENARIO CREATED BY PLAYER. CONTEXT: ", "").split(". INSTRUCTIONS:")[0]
    : baseContext;

  const prompt = `
    ROLE: Simulation Architect.

    INPUT SCENARIO SEED:
    "${coreContent}"

    OBJECTIVE:
    Transform this seed into a highly detailed "Classified Dossier" for a strategy game.
    Determine if this is a WAR, a BUSINESS SIMULATION, a POLITICAL CAMPAIGN, or a SURVIVAL SCENARIO.

    REQUIREMENTS:
    1. **Specific Assets**: Invent specific names (e.g. "USS Saratoga" for war, "Project X-1" for business).
    2. **Real Historical Figures**: Use real people if possible.
    3. **Numbers**: plausible specific numbers.
    4. **Structure**: Timeline, Key Assets, Active Threats.
  `;

  try {
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
    });
    return response.text || baseContext;
  } catch (e) {
    console.error("Scenario enrichment failed, falling back to raw seed", e);
    return baseContext;
  }
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();
  const fullDossier = await enrichScenario(scenarioContext);

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: INITIALIZE TIMELINE ===

    OFFICIAL ENRICHED DOSSIER:
    ${fullDossier}

    TASK:
    Construct Turn 1 based strictly on the Dossier.
    - DEFINE the "Primary Dynamic Stat" based on the scenario type.
    - Populate the "World Ledger" using generic keys.
    - GENERATE A DETAILED 3-PARAGRAPH NARRATIVE REPORT.
    - **Execution Analysis**: Since this is Turn 1, set 'outcomeCategory' to 'VICTORY' (Placeholder), 'outcomeLabel' to 'Timeline Initialization' and 'directiveType' to 'STANDARD'.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Failed to init game:", error);
    throw error;
  }
};

export const consultAdvisor = async (
  advisor: any, // Typed loosely here as we pass the whole object
  currentContext: string,
  userQuestion: string
): Promise<string> => {
  const ai = getClient();

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVISOR CONSULTATION ===

    CURRENT REPORT:
    ${currentContext}

    YOUR PERSONA:
    Name: ${advisor.name}
    Role: ${advisor.role}
    Bias: ${advisor.bias}
    Your previous advice: "${advisor.advice}"

    USER QUESTION:
    "${userQuestion}"

    TASK:
    Answer the user's question directly in character. Keep it brief.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "I have no comment.";
  } catch (error) {
    return "Comm-link disrupted.";
  }
};

export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  choiceDetails: string | null,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  const fullHistoryLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Stats: S:${h.statsSnapshot.stability} W:${h.statsSnapshot.wealth} Support:${h.statsSnapshot.support} ${h.statsSnapshot.primaryStatLabel}:${h.statsSnapshot.primaryStatValue}`
  ).join("\n");

  const latestState = currentHistory[currentHistory.length - 1];
  const currentLedger = latestState.ledgerSnapshot;

  let actionDescription = "";
  if (customInput) {
    actionDescription = `Player input custom directive: "${customInput}"`;
  } else {
    actionDescription = `Player selected: "${playerChoiceText}".`;
    if (choiceDetails) {
        actionDescription += `\n\n=== EXECUTION DETAILS ===\n${choiceDetails}\n=========================================`;
    }
  }

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVANCE TIMELINE ===

    HISTORY LOG:
    ${fullHistoryLog}

    CURRENT WORLD LEDGER (Facts):
    ${JSON.stringify(currentLedger, null, 2)}

    PREVIOUS INTEL REPORT:
    Year: ${latestState.year}
    Briefing: ${latestState.narrative}

    PLAYER DECISION:
    ${actionDescription}

    TASK:
    1. **ADJUDICATE**: 
       - Determine the \`outcomeCategory\` based on the player's choice and the "Adjudication Matrix".
       - **CRITICAL**: If the player took a HIGH/EXTREME Risk, do NOT default to Partial Success. If they fail, give them a **CRITICAL FAILURE**. If they succeed, give them a **VICTORY** (Decisive Triumph).
    2. **CALCULATE**: Apply the consequences.
    3. **NARRATE**: Write the response based on the category.
    4. **AUTOPSY (Execution Analysis)**:
       - Populate the \`executionAnalysis\` object.
       - \`outcomeCategory\`: Must be one of ['VICTORY', 'PARTIAL_SUCCESS', 'PARTIAL_FAILURE', 'CRITICAL_FAILURE'].
       - \`outcomeLabel\`: A plain language description matching the category (e.g. "Operational Success", "Catastrophic Collapse").
    5. **UPDATE**: Generate Turn Data (Intel, News, Advisors).
       - **CRITICAL**: GENERATE 4 NEW DIVERSE CHOICES for the next turn.

    CRITICAL: Maintain the "Primary Dynamic Stat" label used in previous turns (${latestState.statsSnapshot.primaryStatLabel}).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

