);

interface GameInterfaceProps {
  initialTurn: TurnData;
  onRestart: () => void;
}

export const GameInterface: React.FC<GameInterfaceProps> = ({ initialTurn, onRestart }) => {
  const [history, setHistory] = useState<HistoryEntry[]>([{
    turnNumber: 1,
    year: initialTurn.year,
    narrative: initialTurn.narrative,
    eventTitle: initialTurn.eventTitle,
    statsSnapshot: initialTurn.stats,
    statsDelta: initialTurn.statsDelta,
    statsReasoning: initialTurn.statsReasoning,
    ledgerSnapshot: initialTurn.ledger,
    executionAnalysis: initialTurn.executionAnalysis
  }]);

  const [currentTurnData, setCurrentTurnData] = useState<TurnData>(initialTurn);
  const [loading, setLoading] = useState(false);
  const [customInput, setCustomInput] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [showLedger, setShowLedger] = useState(false);
  const [expandedChoiceId, setExpandedChoiceId] = useState<string | null>(null);

  const lastTurnRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;
    }
  }, [customInput]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (!loading && lastTurnRef.current) {
        lastTurnRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }, 100);
    return () => clearTimeout(timer);
  }, [history.length, loading]);

  const handleTurn = async (choiceText: string, details: string | null = null, isCustom: boolean = false) => {
    if (loading || currentTurnData.gameOver) return;

    setLoading(true);
    setError(null);
    setExpandedChoiceId(null);

    const updatedHistory = [...history];
    updatedHistory[updatedHistory.length - 1].userChoice = choiceText;
    setHistory(updatedHistory);

    try {
      const nextTurnData = await processTurn(updatedHistory, choiceText, details, isCustom ? choiceText : undefined);

      const newEntry: HistoryEntry = {
        turnNumber: updatedHistory.length + 1,
        year: nextTurnData.year,
        narrative: nextTurnData.narrative,
        eventTitle: nextTurnData.eventTitle,
        statsSnapshot: nextTurnData.stats,
        statsDelta: nextTurnData.statsDelta,
        statsReasoning: nextTurnData.statsReasoning,
        ledgerSnapshot: nextTurnData.ledger,
        executionAnalysis: nextTurnData.executionAnalysis
      };

      setHistory(prev => [...prev, newEntry]);
      setCurrentTurnData(nextTurnData);
      setCustomInput('');
    } catch (err) {
      setError("The engine failed to process the turn. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const renderDelta = (val: number) => {
    if (val > 0) return <span className="text-emerald-400 flex items-center gap-1 font-mono font-bold"><TrendingUp size={14} /> +{val}</span>;
    if (val < 0) return <span className="text-red-400 flex items-center gap-1 font-mono font-bold"><TrendingDown size={14} /> {val}</span>;
    return <span className="text-gray-600 flex items-center gap-1 font-mono font-bold"><Minus size={14} /> -</span>;
  };

  const renderChoiceButton = (choice: Choice) => {
    const isExpanded = expandedChoiceId === choice.id;
    let borderColor = 'border-gray-700 hover:border-gray-500';
    let typeColor = 'text-gray-500';
    let glowClass = "";

    if (choice.type === 'force') {
      borderColor = 'border-red-900/40 hover:border-red-500/80';
      typeColor = 'text-red-500';
      glowClass = "from-red-900/20 to-transparent";
    } else if (choice.type === 'diplomacy') {
      borderColor = 'border-blue-900/40 hover:border-blue-500/80';
      typeColor = 'text-blue-500';
      glowClass = "from-blue-900/20 to-transparent";
    } else if (choice.type === 'profit') {
      borderColor = 'border-yellow-900/40 hover:border-yellow-500/80';
      typeColor = 'text-yellow-500';
      glowClass = "from-yellow-900/20 to-transparent";
    } else if (choice.type === 'innovation') {
      borderColor = 'border-purple-900/40 hover:border-purple-500/80';
      typeColor = 'text-purple-500';
      glowClass = "from-purple-900/20 to-transparent";
    }

    if (isExpanded) {
        borderColor = 'border-emerald-500/50 ring-1 ring-emerald-500/30';
    }

    const getRiskColor = (r: string) => {
      switch(r) {
        case 'LOW': return 'bg-emerald-900/50 text-emerald-400';
        case 'MEDIUM': return 'bg-yellow-900/50 text-yellow-400';
        case 'HIGH': return 'bg-orange-900/50 text-orange-400';
        case 'EXTREME': return 'bg-red-900/50 text-red-400';
        default: return 'bg-gray-800 text-gray-400';
      }
    }

    const getConfidenceColor = (c: string) => {
      switch(c) {
        case 'HIGH': return 'text-emerald-400 border-emerald-900/50';
        case 'MEDIUM': return 'text-yellow-400 border-yellow-900/50';
        case 'LOW': return 'text-orange-500 border-orange-900/50';
        case 'VOLATILE': return 'text-red-500 border-red-900/50 animate-pulse';
        default: return 'text-gray-400 border-gray-700';
      }
    }

    return (
      <div
        key={choice.id}
        onClick={() => !isExpanded && setExpandedChoiceId(choice.id)}
        className={`w-full text-left rounded-lg border ${borderColor} bg-gray-900/80 transition-all duration-200 group relative overflow-hidden shadow-lg flex flex-col ${isExpanded ? 'scale-[1.01] z-10' : 'hover:scale-[1.01] cursor-pointer'}`}
      >
        <div className={`absolute inset-0 bg-gradient-to-br ${glowClass} opacity-0 group-hover:opacity-100 transition-opacity`}></div>
        <div className="p-5 relative z-10">
            <div className="flex justify-between items-start w-full mb-3">
                <span className={`text-xs uppercase tracking-widest font-mono ${typeColor}`}>{choice.type}</span>
                <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded ${getRiskColor(choice.risk)}`}>
                    Risk: {choice.risk}
                </span>
            </div>
            <span className="text-gray-200 group-hover:text-white font-medium leading-snug text-lg block mb-2">{choice.text}</span>
            {choice.projectedCost && !isExpanded && (
                <div className="mt-1">
                    <span className="text-xs text-gray-500 italic flex items-center gap-1">
                    <AlertTriangle size={10} /> {choice.projectedCost}
                    </span>
                </div>
            )}
            {choice.detailedDescription && (
                <div className="mt-4 p-3 bg-black/30 rounded border-l-2 border-gray-700">
                    <h5 className="text-[10px] font-mono text-emerald-500 uppercase mb-1 flex items-center gap-1">
                        <Target size={10} /> Strategic Analysis
                    </h5>
                    <p className="text-xs text-gray-400 leading-relaxed">{choice.detailedDescription}</p>
                </div>
            )}
            {isExpanded && (
                <div className="mt-4 pt-4 border-t border-gray-700/50 animate-fade-in space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {choice.forecastRange && (
                            <div className="bg-emerald-900/10 p-3 rounded border border-emerald-900/30">
                                <h5 className="text-[10px] font-mono text-emerald-400 uppercase mb-1 flex items-center gap-1"><Percent size={10} /> Success Probability</h5>
                                <p className="text-sm text-gray-300 font-mono font-bold">{choice.forecastRange}</p>
                            </div>
                        )}
                        {choice.forecastConfidence && (
                            <div className={`bg-black/30 p-3 rounded border ${getConfidenceColor(choice.forecastConfidence)}`}>
                                <h5 className="text-[10px] font-mono uppercase mb-1 flex items-center gap-1 opacity-80">
                                    {choice.forecastConfidence === 'HIGH' ? <Eye size={10}/> : <EyeOff size={10}/>} 
                                    Intel Confidence
                                </h5>
                                <p className="text-sm font-mono font-bold tracking-widest">{choice.forecastConfidence}</p>
                            </div>
                        )}
                        {choice.projectedCost && (
                            <div className="md:col-span-2 bg-yellow-900/10 p-3 rounded border border-yellow-900/30">
                                <h5 className="text-[10px] font-mono text-yellow-500 uppercase mb-1 flex items-center gap-1"><AlertTriangle size={10} /> Estimated Cost</h5>
                                <p className="text-sm text-gray-300 font-mono">{choice.projectedCost}</p>
                            </div>
                        )}
                    </div>
                    {choice.technicalReport && (
                        <div>
                            <h5 className="text-[10px] font-mono text-blue-400 uppercase mb-2 flex items-center gap-1"><FileText size={10} /> Operational Briefing</h5>
                            <div className="text-xs text-gray-400 leading-relaxed space-y-2 border-l border-blue-900/50 pl-3">
                                {choice.technicalReport.split('\n\n').map((para, i) => (
                                    <p key={i}>{para}</p>
                                ))}
                            </div>
                        </div>
                    )}
                    <div className="flex gap-3 pt-2">
                        <button 
                            onClick={(e) => { e.stopPropagation(); setExpandedChoiceId(null); }}
                            className="flex-1 py-3 text-xs font-bold text-gray-400 hover:text-white bg-gray-800 hover:bg-gray-700 rounded transition-colors uppercase tracking-wider"
                        >
                            Cancel
                        </button>
                        <button 
                             onClick={(e) => { e.stopPropagation(); handleTurn(choice.text, choice.technicalReport); }}
                             className="flex-[2] py-3 text-xs font-bold text-black bg-emerald-500 hover:bg-emerald-400 rounded transition-colors flex items-center justify-center gap-2 uppercase tracking-wider shadow-lg shadow-emerald-900/20"
                        >
                            <CheckCircle size={14} /> Execute Protocol
                        </button>
                    </div>
                </div>
            )}
        </div>
        {!isExpanded && (
            <div className="absolute right-4 bottom-4 opacity-0 group-hover:opacity-50 transition-opacity">
                <ChevronDown size={16} className="text-gray-500" />
            </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-screen bg-gray-950 text-gray-200 font-serif">
      <StatBar stats={currentTurnData.stats} year={currentTurnData.year} />
      <div className="flex-grow overflow-y-auto scroll-smooth">
        <div className="max-w-4xl mx-auto p-4 md:p-8 pb-24 space-y-12">
          {history.map((entry, index) => {
            const isCurrent = index === history.length - 1;
            return (
              <div 
                key={index} 
                ref={isCurrent ? lastTurnRef : null}
                className={`animate-fade-in ${isCurrent ? 'opacity-100' : 'opacity-60 grayscale hover:grayscale-0 hover:opacity-100 transition-all duration-500'}`}
              >
                <div className="flex items-center gap-4 mb-6 opacity-40">
                  <div className="h-px bg-gray-700 flex-grow"></div>
                  <span className="text-xs font-mono uppercase tracking-widest text-emerald-500">
                    {index === 0 ? 'Divergence Point' : `Turn ${entry.turnNumber}`}
                  </span>
                  <div className="h-px bg-gray-700 flex-grow"></div>
                </div>
                <div className="space-y-6">
                  <h2 className="text-3xl text-emerald-100 font-bold font-serif text-center mb-8">{entry.eventTitle}</h2>
                  {isCurrent ? (
                    <>
                       <NewsTicker news={currentTurnData.news} />
                       <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                          <div className="lg:col-span-2 bg-gray-900 border border-gray-700 rounded-lg p-6 shadow-lg relative flex flex-col gap-4">
                             <div className="absolute -top-3 left-4 bg-gray-950 px-2 text-xs font-mono text-red-500 border border-red-900 rounded flex items-center gap-1">
                                <Lock size={10} /> TOP SECRET // EYES ONLY
                             </div>
                             <div className="prose prose-invert prose-lg max-w-none text-gray-300 leading-loose">
                                <p className="whitespace-pre-wrap font-serif text-justify">{currentTurnData.narrative}</p>
                             </div>
                             <div className="mt-8 pt-6 border-t border-gray-800">
                                <h4 className="text-xs font-mono text-gray-500 uppercase tracking-widest mb-3">Impact Assessment</h4>
                                <div className="flex flex-col sm:flex-row sm:items-center gap-6">
                                    <div className="flex gap-4 text-xs">
                                        <div className="flex flex-col items-center">
                                            {renderDelta(entry.statsDelta.stability)}
                                            <span className="text-[10px] text-gray-600 uppercase mt-1">Stability</span>
                                        </div>
                                        <div className="flex flex-col items-center">
                                            {renderDelta(entry.statsDelta.wealth)}
                                            <span className="text-[10px] text-gray-600 uppercase mt-1">Wealth</span>
                                        </div>
                                        <div className="flex flex-col items-center">
                                            {renderDelta(entry.statsDelta.support)}
                                            <span className="text-[10px] text-gray-600 uppercase mt-1">Support</span>
                                        </div>
                                        <div className="flex flex-col items-center">
                                            {renderDelta(entry.statsDelta.primaryStatValue)}
                                            <span className="text-[10px] text-gray-600 uppercase mt-1">{entry.statsSnapshot.primaryStatLabel}</span>
                                        </div>
                                    </div>
                                    <div className="flex-grow pl-0 sm:pl-6 sm:border-l border-gray-800">
                                        <p className="text-sm text-gray-400 italic font-mono leading-relaxed">
                                            "{entry.statsReasoning || "Impact minimal."}"
                                        </p>
                                    </div>
                                </div>
                                {entry.executionAnalysis && <DeclassifiedReport analysis={entry.executionAnalysis} />}
                             </div>
                          </div>
                          <div className="space-y-4">
                             <h3 className="text-xs font-mono uppercase text-gray-500 flex items-center gap-2"><MessageSquare size={12}/> Advisory Council</h3>
                             {currentTurnData.advisors.map((adv) => (
                               <AdvisorCard key={adv.id} advisor={adv} context={currentTurnData.narrative} />
                             ))}
                          </div>
                       </div>
                    </>
                  ) : (
                    <div className="prose prose-invert prose-lg max-w-none text-gray-400">
                        <p className="whitespace-pre-wrap">{entry.narrative}</p>
                        {entry.userChoice && (
                          <div className="bg-gray-900/50 border-l-2 border-emerald-700 pl-4 py-2 mt-4 rounded-r">
                            <p className="text-xs font-mono text-emerald-600 mb-1 uppercase tracking-wider">Historical Decision</p>
                            <p className="text-sm text-gray-300 italic">"{entry.userChoice}"</p>
                          </div>
                        )}
                        {entry.executionAnalysis && <DeclassifiedReport analysis={entry.executionAnalysis} />}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
          {loading && (
            <div className="flex flex-col items-center justify-center py-12 animate-pulse gap-4 text-emerald-500/70">
              <RefreshCw className="animate-spin w-8 h-8" />
              <span className="font-mono text-sm uppercase tracking-widest">Consulting Intelligence...</span>
            </div>
          )}
          {error && (
              <div className="bg-red-900/20 border border-red-800 text-red-300 p-6 rounded-lg flex items-start gap-4">
                  <AlertTriangle className="flex-shrink-0 mt-1" />
                  <div>
                    <p className="font-bold mb-1">Simulation Error</p>
                    <p className="text-sm">{error}</p>
                    <button onClick={() => setError(null)} className="mt-2 text-xs underline hover:text-white">Dismiss</button>
                  </div>
              </div>
          )}
          {!currentTurnData.gameOver && !loading && (
             <div className="mt-12 pt-8 animate-fade-in border-t border-gray-800">
                 <div className="flex justify-between items-end mb-6">
                    <div className="flex items-center gap-3">
                        <Terminal size={18} className="text-emerald-500" />
                        <h3 className="text-sm font-mono text-emerald-500 uppercase tracking-widest">Command Center</h3>
                    </div>
                    <button 
                        onClick={() => setShowLedger(!showLedger)}
                        className="text-xs font-mono text-blue-400 hover:text-blue-300 uppercase flex items-center gap-2 bg-gray-900 px-3 py-1 rounded border border-blue-900/50 hover:border-blue-500 transition-all"
                    >
                        {showLedger ? 'Hide Intel' : 'View Strategic Intel'}
                    </button>
                 </div>
                 {showLedger && <LedgerPanel ledger={currentTurnData.ledger} />}
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                    {currentTurnData.choices.map(renderChoiceButton)}
                 </div>
                 <div className="relative group">
                    <div className="absolute -inset-0.5 bg-gradient-to-r from-emerald-900 to-blue-900 rounded-lg blur opacity-20 group-hover:opacity-40 transition duration-1000"></div>
                    <div className="relative flex items-end bg-gray-950 rounded-lg border border-gray-700 shadow-inner">
                        <textarea
                            ref={textareaRef}
                            value={customInput}
                            onChange={(e) => setCustomInput(e.target.value)}
                            placeholder="Overwrite protocol with custom directive..."
                            rows={1}
                            className="w-full bg-transparent border-none rounded-lg pl-5 pr-14 py-4 focus:ring-0 text-base font-mono resize-none overflow-hidden"
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && !e.shiftKey) {
                                    e.preventDefault();
                                    if(customInput) handleTurn(customInput, null, true);
                                }
                            }}
                        />
                        <button 
                            onClick={() => customInput && handleTurn(customInput, null, true)}
                            disabled={!customInput}
                            className="absolute right-3 bottom-3 p-2 bg-emerald-900/20 text-emerald-500 hover:bg-emerald-800 hover:text-emerald-100 rounded-md transition-all disabled:opacity-0 disabled:pointer-events-none"
                        >
                            <Send size={20} />
                        </button>
                    </div>
                 </div>
             </div>
          )}
          {currentTurnData.gameOver && !loading && (
             <div className="bg-gray-800 border border-yellow-700/50 p-8 rounded-xl text-center shadow-2xl mt-12">
                <h3 className="text-3xl font-bold text-yellow-500 mb-4">Timeline Terminated</h3>
                <p className="text-gray-300 mb-8">The simulation has reached a conclusion.</p>
                <button 
                  onClick={onRestart}
                  className="bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-lg font-bold shadow-lg transition-transform hover:scale-105 uppercase tracking-wide text-sm"
                >
                  Initialize New Divergence
                </button>
             </div>
          )}
          <div className="h-4" />
        </div>
      </div>
    </div>
  );
};

export interface GameStats {
  stability: number;
  wealth: number;
  support: number; // Formerly 'population' - represents generic external validation/votes/fans
  primaryStatLabel: string; // Dynamic label (e.g. "Military Readiness", "Innovation", "Infection Rate")
  primaryStatValue: number; // The value for the dynamic stat
}

export interface StatsDelta {
  stability: number;
  wealth: number;
  support: number;
  primaryStatValue: number;
}

export interface WorldLedger {
  externalRelations: string[]; // Generalized from diplomaticStatus
  activeThreats: string[];     // Generalized from activeConflicts
  internalPolicies: string[];  // Generalized from domesticPolicies
  keyFigures: string[];
  keyAssets: string[];         // Generalized from militaryAssets
}

export interface Advisor {
  id: string;
  name: string;
  role: string; 
  advice: string; 
  bias: 'force' | 'diplomacy' | 'profit' | 'innovation'; // Generalized biases
}

export interface NewsFlash {
  source: string; 
  headline: string;
}

export interface Choice {
  id: string;
  text: string;
  type: 'diplomacy' | 'force' | 'profit' | 'innovation'; // Generalized types
  risk: 'LOW' | 'MEDIUM' | 'HIGH' | 'EXTREME'; 
  projectedCost?: string; 
  detailedDescription: string; 
  forecastRange: string; // e.g. "20-40%" or "Low-Medium"
  forecastConfidence: 'HIGH' | 'MEDIUM' | 'LOW' | 'VOLATILE'; // The Fog of War indicator
  technicalReport: string; 
}

export interface ExecutionAnalysis {
  directiveType: 'STANDARD' | 'CUSTOM';
  perceivedRisk: 'LOW' | 'MEDIUM' | 'HIGH' | 'EXTREME';
  forecastedRange: string; // e.g. "10-30%"
  forecastConfidence: 'HIGH' | 'MEDIUM' | 'LOW' | 'VOLATILE';
  outcomeCategory: 'VICTORY' | 'PARTIAL_SUCCESS' | 'PARTIAL_FAILURE' | 'CRITICAL_FAILURE'; // Logic driver
  outcomeLabel: string; // Plain language: "Strategic Success", "Pyrrhic Victory", "Total Failure", "Mitigated Disaster"
  resourcesConsumed: string; // e.g. "Stability (-10), Wealth (-5)"
}

export interface TurnData {
  year: string;
  eventTitle: string;

  // Layer 1: Public
  news: NewsFlash[];

  // Layer 2: Private/Secret
  narrative: string; 

  // Layer 3: Counsel
  advisors: Advisor[];

  stats: GameStats;
  statsDelta: StatsDelta; 
  statsReasoning: string; 
  ledger: WorldLedger;
  choices: Choice[];
  executionAnalysis?: ExecutionAnalysis; // Optional for the very first turn
  gameOver: boolean;
}

export interface HistoryEntry {
  turnNumber: number;
  year: string;
  narrative: string;
  eventTitle: string;
  statsSnapshot: GameStats;
  statsDelta: StatsDelta;
  statsReasoning: string;
  ledgerSnapshot: WorldLedger;
  userChoice?: string;
  executionAnalysis?: ExecutionAnalysis;
}

export interface Scenario {
  id: string;
  title: string;
  description: string;
  startingYear: string;
  imageUrl: string;
  promptContext: string;
}

export enum GameStatus {
  MENU = 'MENU',
  LOADING = 'LOADING',
  PLAYING = 'PLAYING',
  ENDED = 'ENDED'
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { TurnData, HistoryEntry } from '../types';

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY environment variable is not set.");
  }
  return new GoogleGenAI({ apiKey });
};

// Generic schema for the Universal Simulation Engine
const turnSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    year: { type: Type.STRING },
    eventTitle: { type: Type.STRING },

    news: {
      type: Type.ARRAY,
      description: "3 distinct news headlines reflecting public perception.",
      items: {
        type: Type.OBJECT,
        properties: {
          source: { type: Type.STRING, description: "Name of the publication or source." },
          headline: { type: Type.STRING }
        },
        required: ["source", "headline"]
      }
    },

    narrative: { type: Type.STRING, description: "The classified situation report. A detailed, 3-paragraph dossier (approx 300 words). Paragraph 1: Immediate incident. Paragraph 2: Broader reaction. Paragraph 3: Hidden threats or opportunities." },

    advisors: {
      type: Type.ARRAY,
      description: "2 Advisors with conflicting viewpoints.",
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          name: { type: Type.STRING },
          role: { type: Type.STRING },
          advice: { type: Type.STRING, description: "First-person perspective advice." },
          bias: { type: Type.STRING, enum: ['force', 'diplomacy', 'profit', 'innovation'] }
        },
        required: ["id", "name", "role", "advice", "bias"]
      }
    },

    stats: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER, description: "Internal cohesion/loyalty (0-100)." },
        wealth: { type: Type.INTEGER, description: "Resources/Money/Budget (0-100)." },
        support: { type: Type.INTEGER, description: "External validation/Popularity/Shareholder Trust (0-100)." },
        primaryStatLabel: { type: Type.STRING, description: "The name of the dynamic 4th stat (e.g. 'Military Readiness', 'Innovation', 'Infection Rate')." },
        primaryStatValue: { type: Type.INTEGER, description: "Value of the dynamic stat (0-100)." },
      },
      required: ["stability", "wealth", "support", "primaryStatLabel", "primaryStatValue"]
    },
    statsDelta: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER },
        wealth: { type: Type.INTEGER },
        support: { type: Type.INTEGER },
        primaryStatValue: { type: Type.INTEGER },
      },
      required: ["stability", "wealth", "support", "primaryStatValue"]
    },
    statsReasoning: { type: Type.STRING, description: "1-2 sentence explanation of why stats changed." },

    ledger: {
      type: Type.OBJECT,
      properties: {
        externalRelations: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Allies, Partners, or Treaties." },
        activeThreats: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Wars, Lawsuits, Competitors, or Disasters." },
        internalPolicies: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Laws, Corporate Strategies, or Social Reforms." },
        keyFigures: { type: Type.ARRAY, items: { type: Type.STRING } },
        keyAssets: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Specific named assets (Armies, Tech Labs, Patents, Fleets)." }
      },
      required: ["externalRelations", "activeThreats", "internalPolicies", "keyFigures", "keyAssets"]
    },

    choices: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          text: { type: Type.STRING, description: "The action title." },
          type: { type: Type.STRING, enum: ['diplomacy', 'force', 'profit', 'innovation'] },
          risk: { type: Type.STRING, enum: ['LOW', 'MEDIUM', 'HIGH', 'EXTREME'] },
          projectedCost: { type: Type.STRING },
          detailedDescription: { type: Type.STRING, description: "3-4 sentence strategic analysis of immediate effects." },
          forecastRange: { type: Type.STRING, description: "Estimated success rate (e.g., '30-50%', 'Low-Medium')." },
          forecastConfidence: { type: Type.STRING, enum: ['HIGH', 'MEDIUM', 'LOW', 'VOLATILE'], description: "Reliability of the intel." },
          technicalReport: { type: Type.STRING, description: "2-3 paragraph operational report on execution details. MUST be in-universe." }
        },
        required: ["id", "text", "type", "risk", "detailedDescription", "forecastRange", "forecastConfidence", "technicalReport"]
      }
    },

    executionAnalysis: {
        type: Type.OBJECT,
        description: "Post-action analysis of the move that was JUST taken.",
        properties: {
            directiveType: { type: Type.STRING, enum: ['STANDARD', 'CUSTOM'] },
            perceivedRisk: { type: Type.STRING, enum: ['LOW', 'MEDIUM', 'HIGH', 'EXTREME'] },
            forecastedRange: { type: Type.STRING },
            forecastConfidence: { type: Type.STRING, enum: ['HIGH', 'MEDIUM', 'LOW', 'VOLATILE'] },
            outcomeCategory: { type: Type.STRING, enum: ['VICTORY', 'PARTIAL_SUCCESS', 'PARTIAL_FAILURE', 'CRITICAL_FAILURE'], description: "The internal classification of the result." },
            outcomeLabel: { type: Type.STRING, description: "Plain language description of the result (e.g., 'Strategic Success', 'Pyrrhic Victory', 'Total Failure'). DO NOT include internal codenames." },
            resourcesConsumed: { type: Type.STRING, description: "Summary of cost." }
        },
        required: ["directiveType", "perceivedRisk", "forecastedRange", "forecastConfidence", "outcomeCategory", "outcomeLabel", "resourcesConsumed"]
    },

    gameOver: { type: Type.BOOLEAN }
  },
  required: ["year", "eventTitle", "news", "narrative", "advisors", "stats", "statsDelta", "statsReasoning", "ledger", "choices", "gameOver", "executionAnalysis"]
};

const SYSTEM_INSTRUCTION = `
You are the "Chronus" Universal Divergence Engine. You are a Grand Strategy Simulation AI.

=== CORE MECHANIC: CONTEXT ===
Determine the context of the scenario:
1. **Military Context**: Dynamic Stat = "Readiness". Ledger = Armies, Enemies.
2. **Corporate Context**: Dynamic Stat = "Market Share". Ledger = Patents, Competitors.
3. **Political Context**: Dynamic Stat = "Democratic Integrity" or "Influence". Ledger = Donors, Opponents.
4. **Crisis Context**: Dynamic Stat = "Infection Rate". Ledger = Hospitals, Outbreaks.

=== THE ADJUDICATION MATRIX (OUTCOME LOGIC) ===
Classify all results into exactly one of these 4 categories.

1. **VICTORY** (Green): Objective achieved fully. No significant downsides.
   - *Logic*: Use this for High Confidence + Good Stats/Feasible Plans.
   - *Scaling*:
     - Low Risk move -> "Operational Success" (Small gain).
     - High Risk move -> "Decisive Triumph" (Massive gain).

2. **PARTIAL SUCCESS** (Light Green): Objective achieved, but with a cost.
   - *Logic*: **SUCCESS > DOWNSIDE**. The player got what they wanted, but it hurt.
   - *Key Constraint*: The cost must *not* overshadow the victory. It is a net positive.
   - *Labels*: "Costly Success", "Pyrrhic Victory", "Strategic Trade-off".

3. **PARTIAL FAILURE** (Light Red): Objective failed, but with an upside.
   - *Logic*: **FAILURE > UPSIDE**. The player missed their main goal, but found a silver lining.
   - *Key Constraint*: The upside must *not* overshadow the failure. It is a net negative.
   - *Labels*: "Mitigated Defeat", "Stalemate", "Moral Victory".

4. **CRITICAL FAILURE** (Red): Objective failed completely. Resources lost.
   - *Logic*: Pure loss. Do not cushion the blow.
   - *Scaling*:
     - Low Risk move -> "Operational Setback" (Annoying loss).
     - High Risk move -> "Catastrophic Collapse" (Game-altering loss).

=== OBSCURITY PROTOCOL (CRITICAL) ===
You must maintain the illusion of a realistic simulation.
**DO NOT** use the terms "Partial Success" or "Critical Failure" in the \`outcomeLabel\`.
Use immersive, descriptive terms like "Strategic Success", "Costly Advance", "Total Debacle".

=== CHOICE GENERATION PROTOCOL ===
You must generate exactly 4 strategic choices. They MUST be diverse:
1. **Option 1 (The Safe Bet)**: Low Risk. Conventional. Focus on Diplomacy or Econ.
2. **Option 2 (Hard Power)**: Medium Risk. Conventional. Focus on Force or Aggression.
3. **Option 3 (The Wildcard)**: High Risk. Creative/Unorthodox.
4. **Option 4 (The Desperate Measure)**: Extreme Risk. Creative/Unorthodox.

=== FOG OF WAR PROTOCOL ===
When defining \`forecastConfidence\`:
- **HIGH**: Standard, well-understood moves.
- **VOLATILE / LOW**: Experimental, chaotic, or secretive moves.
- **Rule**: If Confidence was LOW/VOLATILE, you MUST introduce a twist (Positive or Negative) regardless of stats.

=== NARRATIVE STYLE ===
- Tone: Serious, high-stakes.
- Detail: Use specific names of assets, people, and organizations.
- Causality: Brutal realism.
`;

const enrichScenario = async (baseContext: string): Promise<string> => {
  const ai = getClient();

  const isCustom = baseContext.startsWith("CUSTOM SCENARIO");
  const coreContent = isCustom 
    ? baseContext.replace("CUSTOM SCENARIO CREATED BY PLAYER. CONTEXT: ", "").split(". INSTRUCTIONS:")[0]
    : baseContext;

  const prompt = `
    ROLE: Simulation Architect.

    INPUT SCENARIO SEED:
    "${coreContent}"

    OBJECTIVE:
    Transform this seed into a highly detailed "Classified Dossier" for a strategy game.
    Determine if this is a WAR, a BUSINESS SIMULATION, a POLITICAL CAMPAIGN, or a SURVIVAL SCENARIO.

    REQUIREMENTS:
    1. **Specific Assets**: Invent specific names (e.g. "USS Saratoga" for war, "Project X-1" for business).
    2. **Real Historical Figures**: Use real people if possible.
    3. **Numbers**: plausible specific numbers.
    4. **Structure**: Timeline, Key Assets, Active Threats.
  `;

  try {
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
    });
    return response.text || baseContext;
  } catch (e) {
    console.error("Scenario enrichment failed, falling back to raw seed", e);
    return baseContext;
  }
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();
  const fullDossier = await enrichScenario(scenarioContext);

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: INITIALIZE TIMELINE ===

    OFFICIAL ENRICHED DOSSIER:
    ${fullDossier}

    TASK:
    Construct Turn 1 based strictly on the Dossier.
    - DEFINE the "Primary Dynamic Stat" based on the scenario type.
    - Populate the "World Ledger" using generic keys.
    - GENERATE A DETAILED 3-PARAGRAPH NARRATIVE REPORT.
    - **Execution Analysis**: Since this is Turn 1, set 'outcomeCategory' to 'VICTORY' (Placeholder), 'outcomeLabel' to 'Timeline Initialization' and 'directiveType' to 'STANDARD'.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Failed to init game:", error);
    throw error;
  }
};

export const consultAdvisor = async (
  advisor: any, // Typed loosely here as we pass the whole object
  currentContext: string,
  userQuestion: string
): Promise<string> => {
  const ai = getClient();

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVISOR CONSULTATION ===

    CURRENT REPORT:
    ${currentContext}

    YOUR PERSONA:
    Name: ${advisor.name}
    Role: ${advisor.role}
    Bias: ${advisor.bias}
    Your previous advice: "${advisor.advice}"

    USER QUESTION:
    "${userQuestion}"

    TASK:
    Answer the user's question directly in character. Keep it brief.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "I have no comment.";
  } catch (error) {
    return "Comm-link disrupted.";
  }
};

export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  choiceDetails: string | null,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  const fullHistoryLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Stats: S:${h.statsSnapshot.stability} W:${h.statsSnapshot.wealth} Support:${h.statsSnapshot.support} ${h.statsSnapshot.primaryStatLabel}:${h.statsSnapshot.primaryStatValue}`
  ).join("\n");

  const latestState = currentHistory[currentHistory.length - 1];
  const currentLedger = latestState.ledgerSnapshot;

  let actionDescription = "";
  if (customInput) {
    actionDescription = `Player input custom directive: "${customInput}"`;
  } else {
    actionDescription = `Player selected: "${playerChoiceText}".`;
    if (choiceDetails) {
        actionDescription += `\n\n=== EXECUTION DETAILS ===\n${choiceDetails}\n=========================================`;
    }
  }

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVANCE TIMELINE ===

    HISTORY LOG:
    ${fullHistoryLog}

    CURRENT WORLD LEDGER (Facts):
    ${JSON.stringify(currentLedger, null, 2)}

    PREVIOUS INTEL REPORT:
    Year: ${latestState.year}
    Briefing: ${latestState.narrative}

    PLAYER DECISION:
    ${actionDescription}

    TASK:
    1. **ADJUDICATE**: 
       - Determine the \`outcomeCategory\` based on the player's choice and the "Adjudication Matrix".
       - **CRITICAL**: If the player took a HIGH/EXTREME Risk, do NOT default to Partial Success. If they fail, give them a **CRITICAL FAILURE**. If they succeed, give them a **VICTORY** (Decisive Triumph).
    2. **CALCULATE**: Apply the consequences.
    3. **NARRATE**: Write the response based on the category.
    4. **AUTOPSY (Execution Analysis)**:
       - Populate the \`executionAnalysis\` object.
       - \`outcomeCategory\`: Must be one of ['VICTORY', 'PARTIAL_SUCCESS', 'PARTIAL_FAILURE', 'CRITICAL_FAILURE'].
       - \`outcomeLabel\`: A plain language description matching the category (e.g. "Operational Success", "Catastrophic Collapse").
    5. **UPDATE**: Generate Turn Data (Intel, News, Advisors).
       - **CRITICAL**: GENERATE 4 NEW DIVERSE CHOICES for the next turn.

    CRITICAL: Maintain the "Primary Dynamic Stat" label used in previous turns (${latestState.statsSnapshot.primaryStatLabel}).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

