  let outcomeColor = "text-gray-300";
  if (analysis.outcomeCategory === 'VICTORY') outcomeColor = "text-emerald-400"; // Pure Green
  else if (analysis.outcomeCategory === 'PARTIAL_SUCCESS') outcomeColor = "text-emerald-200"; // Light Green
  else if (analysis.outcomeCategory === 'PARTIAL_FAILURE') outcomeColor = "text-red-300"; // Light Red
  else if (analysis.outcomeCategory === 'CRITICAL_FAILURE') outcomeColor = "text-red-500"; // Pure Red
