export interface GameStats {
  stability: number;
  wealth: number;
  support: number; // Formerly 'population' - represents generic external validation/votes/fans
  primaryStatLabel: string; // Dynamic label (e.g. "Military Readiness", "Innovation", "Infection Rate")
  primaryStatValue: number; // The value for the dynamic stat
}

export interface StatsDelta {
  stability: number;
  wealth: number;
  support: number;
  primaryStatValue: number;
}

export interface WorldLedger {
  externalRelations: string[]; // Generalized from diplomaticStatus
  activeThreats: string[];     // Generalized from activeConflicts
  internalPolicies: string[];  // Generalized from domesticPolicies
  keyFigures: string[];
  keyAssets: string[];         // Generalized from militaryAssets
}

export interface Advisor {
  id: string;
  name: string;
  role: string; 
  advice: string; 
  bias: 'force' | 'diplomacy' | 'profit' | 'innovation'; // Generalized biases
}

export interface NewsFlash {
  source: string; 
  headline: string;
}

export interface Choice {
  id: string;
  text: string;
  type: 'diplomacy' | 'force' | 'profit' | 'innovation'; // Generalized types
  risk: 'LOW' | 'MEDIUM' | 'HIGH' | 'EXTREME'; 
  projectedCost?: string; 
  detailedDescription: string; 
  forecastRange: string; // e.g. "20-40%" or "Low-Medium"
  forecastConfidence: 'HIGH' | 'MEDIUM' | 'LOW' | 'VOLATILE'; // The Fog of War indicator
  technicalReport: string; 
}

export interface ExecutionAnalysis {
  directiveType: 'STANDARD' | 'CUSTOM';
  perceivedRisk: 'LOW' | 'MEDIUM' | 'HIGH' | 'EXTREME';
  forecastedRange: string; // e.g. "10-30%"
  forecastConfidence: 'HIGH' | 'MEDIUM' | 'LOW' | 'VOLATILE';
  outcomeCategory: 'VICTORY' | 'PARTIAL_SUCCESS' | 'PARTIAL_FAILURE' | 'CRITICAL_FAILURE'; // Logic driver
  outcomeLabel: string; // Plain language: "Strategic Success", "Pyrrhic Victory", "Total Failure", "Mitigated Disaster"
  resourcesConsumed: string; // e.g. "Stability (-10), Wealth (-5)"
}

export interface TurnData {
  year: string;
  eventTitle: string;

  // Layer 1: Public
  news: NewsFlash[];

  // Layer 2: Private/Secret
  narrative: string; 

  // Layer 3: Counsel
  advisors: Advisor[];

  stats: GameStats;
  statsDelta: StatsDelta; 
  statsReasoning: string; 
  ledger: WorldLedger;
  choices: Choice[];
  executionAnalysis?: ExecutionAnalysis; // Optional for the very first turn
  gameOver: boolean;
}

export interface HistoryEntry {
  turnNumber: number;
  year: string;
  narrative: string;
  eventTitle: string;
  statsSnapshot: GameStats;
  statsDelta: StatsDelta;
  statsReasoning: string;
  ledgerSnapshot: WorldLedger;
  userChoice?: string;
  executionAnalysis?: ExecutionAnalysis;
}

export interface Scenario {
  id: string;
  title: string;
  description: string;
  startingYear: string;
  imageUrl: string;
  promptContext: string;
}

export enum GameStatus {
  MENU = 'MENU',
  LOADING = 'LOADING',
  PLAYING = 'PLAYING',
  ENDED = 'ENDED'
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { TurnData, HistoryEntry } from '../types';

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY environment variable is not set.");
  }
  return new GoogleGenAI({ apiKey });
};

// Generic schema for the Universal Simulation Engine
const turnSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    year: { type: Type.STRING },
    eventTitle: { type: Type.STRING },

    news: {
      type: Type.ARRAY,
      description: "3 distinct news headlines reflecting public perception.",
      items: {
        type: Type.OBJECT,
        properties: {
          source: { type: Type.STRING, description: "Name of the publication or source." },
          headline: { type: Type.STRING }
        },
        required: ["source", "headline"]
      }
    },

    narrative: { type: Type.STRING, description: "The classified situation report. A detailed, 3-paragraph dossier (approx 300 words). Paragraph 1: Immediate incident. Paragraph 2: Broader reaction. Paragraph 3: Hidden threats or opportunities." },

    advisors: {
      type: Type.ARRAY,
      description: "2 Advisors with conflicting viewpoints.",
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          name: { type: Type.STRING },
          role: { type: Type.STRING },
          advice: { type: Type.STRING, description: "First-person perspective advice." },
          bias: { type: Type.STRING, enum: ['force', 'diplomacy', 'profit', 'innovation'] }
        },
        required: ["id", "name", "role", "advice", "bias"]
      }
    },

    stats: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER, description: "Internal cohesion/loyalty (0-100)." },
        wealth: { type: Type.INTEGER, description: "Resources/Money/Budget (0-100)." },
