    },
    statsDelta: {
      type: Type.OBJECT,
      properties: {
        stability: { type: Type.INTEGER },
        wealth: { type: Type.INTEGER },
        support: { type: Type.INTEGER },
        primaryStatValue: { type: Type.INTEGER },
      },
