    },

    choices: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          id: { type: Type.STRING },
          text: { type: Type.STRING, description: "The action title." },
          type: { type: Type.STRING, enum: ['diplomacy', 'force', 'profit', 'innovation'] },
          risk: { type: Type.STRING, enum: ['LOW', 'MEDIUM', 'HIGH', 'EXTREME'] },
          projectedCost: { type: Type.STRING },
          detailedDescription: { type: Type.STRING, description: "3-4 sentence strategic analysis of immediate effects." },
          forecastRange: { type: Type.STRING, description: "Estimated success rate (e.g., '30-50%', 'Low-Medium')." },
          forecastConfidence: { type: Type.STRING, enum: ['HIGH', 'MEDIUM', 'LOW', 'VOLATILE'], description: "Reliability of the intel." },
          technicalReport: { type: Type.STRING, description: "2-3 paragraph operational report on execution details. MUST be in-universe." }
        },
        required: ["id", "text", "type", "risk", "detailedDescription", "forecastRange", "forecastConfidence", "technicalReport"]
      }
    },

    executionAnalysis: {
        type: Type.OBJECT,
        description: "Post-action analysis of the move that was JUST taken.",
        properties: {
            directiveType: { type: Type.STRING, enum: ['STANDARD', 'CUSTOM'] },
            perceivedRisk: { type: Type.STRING, enum: ['LOW', 'MEDIUM', 'HIGH', 'EXTREME'] },
            forecastedRange: { type: Type.STRING },
            forecastConfidence: { type: Type.STRING, enum: ['HIGH', 'MEDIUM', 'LOW', 'VOLATILE'] },
            outcomeCategory: { type: Type.STRING, enum: ['VICTORY', 'PARTIAL_SUCCESS', 'PARTIAL_FAILURE', 'CRITICAL_FAILURE'], description: "The internal classification of the result." },
            outcomeLabel: { type: Type.STRING, description: "Plain language description of the result (e.g., 'Strategic Success', 'Pyrrhic Victory', 'Total Failure'). DO NOT include internal codenames." },
