  else if (analysis.outcomeCategory === 'PARTIAL_FAILURE') outcomeColor = "text-red-300"; // Light Red
  else if (analysis.outcomeCategory === 'CRITICAL_FAILURE') outcomeColor = "text-red-500"; // Pure Red
