export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  choiceDetails: string | null,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  const fullHistoryLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Stats: S:${h.statsSnapshot.stability} W:${h.statsSnapshot.wealth} Support:${h.statsSnapshot.support} ${h.statsSnapshot.primaryStatLabel}:${h.statsSnapshot.primaryStatValue}`
  ).join("\n");

  const latestState = currentHistory[currentHistory.length - 1];
  const currentLedger = latestState.ledgerSnapshot;

  let actionDescription = "";
  if (customInput) {
    actionDescription = `Player input custom directive: "${customInput}"`;
  } else {
    actionDescription = `Player selected: "${playerChoiceText}".`;
    if (choiceDetails) {
        actionDescription += `\n\n=== EXECUTION DETAILS ===\n${choiceDetails}\n=========================================`;
    }
  }

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVANCE TIMELINE ===

    HISTORY LOG:
    ${fullHistoryLog}

    CURRENT WORLD LEDGER (Facts):
    ${JSON.stringify(currentLedger, null, 2)}

    PREVIOUS INTEL REPORT:
    Year: ${latestState.year}
    Briefing: ${latestState.narrative}

    PLAYER DECISION:
    ${actionDescription}

    TASK:
    1. **ADJUDICATE**: 
       - Determine the \`outcomeCategory\` based on the player's choice and the "Adjudication Matrix".
       - **CRITICAL**: If the player took a HIGH/EXTREME Risk, do NOT default to Partial Success. If they fail, give them a **CRITICAL FAILURE**. If they succeed, give them a **VICTORY** (Decisive Triumph).
    2. **CALCULATE**: Apply the consequences.
    3. **NARRATE**: Write the response based on the category.
    4. **AUTOPSY (Execution Analysis)**:
       - Populate the \`executionAnalysis\` object.
       - \`outcomeCategory\`: Must be one of ['VICTORY', 'PARTIAL_SUCCESS', 'PARTIAL_FAILURE', 'CRITICAL_FAILURE'].
       - \`outcomeLabel\`: A plain language description matching the category (e.g. "Operational Success", "Catastrophic Collapse").
    5. **UPDATE**: Generate Turn Data (Intel, News, Advisors).
       - **CRITICAL**: GENERATE 4 NEW DIVERSE CHOICES for the next turn.

    CRITICAL: Maintain the "Primary Dynamic Stat" label used in previous turns (${latestState.statsSnapshot.primaryStatLabel}).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

