const SYSTEM_INSTRUCTION = `
You are the "Chronus" Universal Divergence Engine. You are a Grand Strategy Simulation AI.

=== THE UNIVERSAL ENGINE PROTOCOL ===
You are not writing a story. You are managing a STATEFUL SIMULATION.
Every turn, you must update the "World Ledger" (Entities) and "Plot Arcs".

1. **THE MANIFEST (Physics)**:
   - At the start of the game, define the rules (Currency, Time Unit, Win Condition).
   - RESPECT THE MANIFEST. If the time unit is "Months", do not jump "Years".
   - If the currency is "Energy", do not mention "Dollars".

2. **THE ENTITY LOGIC (Depth)**:
   - Do not just output flavor text. Output ENTITIES with \`power\` and \`loyalty\`.
   - **Calculation Rule**: Outcome = (Your Asset Power + Roll) - (Enemy Power + Difficulty).
   - If an Ally has Low Loyalty (<30), they may betray the player or refuse orders.
   - If an Enemy has High Power (>80), they will actively reduce Player Stats every turn unless countered.

3. **THE ARC SYSTEM (Consistency)**:
   - Identify 1-2 major "Plot Arcs" (e.g. "The Upcoming Election", "The Alien Invasion Fleet").
   - Track their progress (0-100%).
   - When an Arc hits 100%, trigger the CLIMAX event.
   - Do not let the simulation "drift". If the Arc is "Election", every turn must advance towards it.

=== HISTORICAL FIDELITY (CRITICAL) ===
- **Use Real History**: When introducing new characters, events, or technologies, prioritize REAL historical figures, cabinets, and laws from the era.
- **Divergence Logic**: Only diverge from history where the Player's actions or the Scenario's premise logically force it. Everything else (e.g., who is the King of France, what technology exists) should remain historically accurate.
- **Specific Names**: Avoid generic terms like "The General" or "The Minister". Use specific real-world names (e.g., "General Zhukov", "Minister Talleyrand") whenever possible.

=== THE ADJUDICATION MATRIX ===
1. **VICTORY**: Objective met. Entity Power increases.
2. **PARTIAL SUCCESS**: Objective met, but Resources lost or Entity Loyalty drops.
3. **PARTIAL FAILURE**: Objective failed, but gained Intel or minor Entity Loyalty.
4. **CRITICAL FAILURE**: Objective failed. Entity destroyed or betrayed player. Stats plummet.

=== NARRATIVE STYLE ===
- Tone: Serious, high-stakes.
- Focus: Use the names of the Entities defined in your Ledger.
- Detail: Be verbose (300+ words).
`;

const enrichScenario = async (baseContext: string): Promise<string> => {
  const ai = getClient();

  const isCustom = baseContext.startsWith("CUSTOM SCENARIO");
  const coreContent = isCustom 
    ? baseContext.replace("CUSTOM SCENARIO CREATED BY PLAYER. CONTEXT: ", "").split(". INSTRUCTIONS:")[0]
    : baseContext;

  const prompt = `
    ROLE: Simulation Architect & Historian.
    INPUT SCENARIO SEED: "${coreContent}"
    OBJECTIVE: Transform this seed into a highly detailed "Classified Dossier".

    CRITICAL INSTRUCTIONS FOR HISTORICAL ACCURACY:
    1. **Identify Real Figures**: Search your knowledge base for the actual cabinet members, generals, opposition leaders, and foreign heads of state active in this specific year/month.
    2. **Populate Entities**: Use these REAL historical figures for the Allies, Enemies, and Assets. Do not invent characters if real ones exist.
    3. **Define Manifest**:
       - Currency/Resources?
       - Time Scale?
       - Key Entities?
  `;

  try {
    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: { maxOutputTokens: 8192, thinkingConfig: { thinkingBudget: 4096 } }
    });
    return response.text || baseContext;
  } catch (e) {
    console.error("Scenario enrichment failed", e);
    return baseContext;
  }
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();
  const fullDossier = await enrichScenario(scenarioContext);

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === PHASE 1: GENESIS ===

    DOSSIER (Use this for factual grounding):
    ${fullDossier}

    TASK:
    1. **Create the Simulation Manifest**: Define the genre, time unit, and stat labels.
    2. **Initialize Arcs**: Create 1 main Plot Arc (e.g. "War Progress" or "Election Countdown") starting at 0-10%.
    3. **Populate Ledger**: Create at least 2 Allies, 2 Enemies, and 2 Assets as ENTITIES. **Ensure these use REAL historical names where applicable.**
    4. **Generate Turn 1**: The inciting incident.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        maxOutputTokens: 20000,
        thinkingConfig: { thinkingBudget: 12288 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Failed to init game:", error);
    throw error;
  }
};

export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  choiceDetails: string | null,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  // We need to pass the Manifest and recent Arcs to ensure consistency
  const latestState = currentHistory[currentHistory.length - 1];
  const manifest = latestState.manifestSnapshot;

  // Compact history log
  const historyLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Stats: ${JSON.stringify(h.statsSnapshot)}`
  ).join("\n");

  const actionDescription = customInput 
    ? `Player input custom directive: "${customInput}"` 
    : `Player selected: "${playerChoiceText}".\nEXECUTION DETAILS: ${choiceDetails}`;

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVANCE SIMULATION ===

    **SIMULATION MANIFEST (DO NOT VIOLATE)**:
    ${JSON.stringify(manifest, null, 2)}

    **CURRENT ARCS (UPDATE THESE)**:
    ${JSON.stringify(latestState.arcsSnapshot, null, 2)}

    **CURRENT LEDGER (ENTITIES)**:
    ${JSON.stringify(latestState.ledgerSnapshot, null, 2)}

    HISTORY:
    ${historyLog}

    PREVIOUS NARRATIVE:
    ${latestState.narrative}

    PLAYER DECISION:
    ${actionDescription}

    TASK:
    1. **CALCULATE**: Compare Player Resources/Assets vs Enemy Power.
    2. **ADJUDICATE**: Determine Outcome Category.
    3. **UPDATE STATE**:
       - Update Arc Progress (did this move bring us closer to the climax?).
       - Update Entity Power/Loyalty (did we hurt the enemy? did we annoy an ally?).
       - Update Global Stats (${manifest.statsConfig.wealthLabel}, ${manifest.statsConfig.stabilityLabel}, etc).
    4. **NARRATE**: Write the response matching the genre "${manifest.genre}". **Cite specific historical details in the narrative.**
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        maxOutputTokens: 20000,
        thinkingConfig: { thinkingBudget: 12288 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

export const consultAdvisor = async (
    advisor: any, 
    currentContext: string,
    userQuestion: string
  ): Promise<string> => {
    const ai = getClient();
    const prompt = `
      ${SYSTEM_INSTRUCTION}
      === ADVISOR CHANNEL ===
      CONTEXT: ${currentContext}
      PERSONA: ${advisor.name} (${advisor.role}). Bias: ${advisor.bias}.
      USER QUESTION: "${userQuestion}"
      TASK: Answer in character.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
      });
      return response.text || "No comment.";
    } catch (error) {
      return "Comm-link disrupted.";
    }
  };

