  ): Promise<string> => {
    const ai = getClient();
    const prompt = `
      ${SYSTEM_INSTRUCTION}
      === ADVISOR CHANNEL ===
      CONTEXT: ${currentContext}
      PERSONA: ${advisor.name} (${advisor.role}). Bias: ${advisor.bias}.
      USER QUESTION: "${userQuestion}"
      TASK: Answer in character.
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
      });
      return response.text || "No comment.";
    } catch (error) {
      return "Comm-link disrupted.";
    }
  };

