export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  choiceDetails: string | null,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  // We need to pass the Manifest and recent Arcs to ensure consistency
  const latestState = currentHistory[currentHistory.length - 1];
  const manifest = latestState.manifestSnapshot;

  // Compact history log
  const historyLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Stats: ${JSON.stringify(h.statsSnapshot)}`
  ).join("\n");

  const actionDescription = customInput 
    ? `Player input custom directive: "${customInput}"` 
    : `Player selected: "${playerChoiceText}".\nEXECUTION DETAILS: ${choiceDetails}`;

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVANCE SIMULATION ===

    **SIMULATION MANIFEST (DO NOT VIOLATE)**:
    ${JSON.stringify(manifest, null, 2)}

    **CURRENT ARCS (UPDATE THESE)**:
    ${JSON.stringify(latestState.arcsSnapshot, null, 2)}

    **CURRENT LEDGER (ENTITIES)**:
    ${JSON.stringify(latestState.ledgerSnapshot, null, 2)}

    HISTORY:
    ${historyLog}

    PREVIOUS NARRATIVE:
    ${latestState.narrative}

    PLAYER DECISION:
    ${actionDescription}

    TASK:
    1. **CALCULATE**: Compare Player Resources/Assets vs Enemy Power.
    2. **ADJUDICATE**: Determine Outcome Category.
    3. **UPDATE STATE**:
       - Update Arc Progress (did this move bring us closer to the climax?).
       - Update Entity Power/Loyalty (did we hurt the enemy? did we annoy an ally?).
       - Update Global Stats (${manifest.statsConfig.wealthLabel}, ${manifest.statsConfig.stabilityLabel}, etc).
    4. **NARRATE**: Write the response matching the genre "${manifest.genre}". **Cite specific historical details in the narrative.**
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        maxOutputTokens: 20000,
        thinkingConfig: { thinkingBudget: 12288 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

