const enrichScenario = async (baseContext: string): Promise<string> => {
  const ai = getClient();

  const isCustom = baseContext.startsWith("CUSTOM SCENARIO");
  const coreContent = isCustom 
    ? baseContext.replace("CUSTOM SCENARIO CREATED BY PLAYER. CONTEXT: ", "").split(". INSTRUCTIONS:")[0]
    : baseContext;

  const prompt = `
    ROLE: Simulation Architect & Historian.
    INPUT SCENARIO SEED: "${coreContent}"
    OBJECTIVE: Transform this seed into a highly detailed "Classified Dossier".

    CRITICAL INSTRUCTIONS FOR ACCURACY:
    1. **EXTRACT & PRESERVE**: Identify every specific Name, Date, and Asset listed in the Input Seed. These MUST appear in the final Dossier exactly as written.

    2. **CASTING CALL (THE "REAL PEOPLE" RULE)**:
       - **MANDATE**: You must populate this world with **REAL PEOPLE**, even for hypothetical roles.
       - **INCUMBENTS**: Use real leaders for real institutions (e.g. "General Brown" for Joint Chiefs).
       - **DRAFT PICKS**: For fictional groups (e.g. "The Resistance"), cast real figures who would plausibly join them. 
         - *Bad:* "Resistance Leader Mark Steele."
         - *Good:* "Resistance Leader Gavin Newsom" or "Strategist Stacey Abrams".
       - **PROHIBITED**: Do NOT use generic names (Aris Thorne, Maxwell Stone). 

    3. **IDENTIFY DILEMMAS**: Explicitly list the "Strategic Dilemmas" or "Tensions" found in the text.
    4. **STRUCTURE**: Organize into Factions, Assets, Threats, and Strategic Dilemmas.
  `;

  try {
    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: { maxOutputTokens: 8192, thinkingConfig: { thinkingBudget: 4096 } }
    });
    return response.text || baseContext;
  } catch (e) {
    console.error("Scenario enrichment failed", e);
    return baseContext;
  }
};

export const initializeGame = async (scenarioContext: string): Promise<TurnData> => {
  const ai = getClient();
  const fullDossier = await enrichScenario(scenarioContext);

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === PHASE 1: GENESIS ===

    DOSSIER (Use this for factual grounding):
    ${fullDossier}

    TASK:
    1. **Create the Simulation Manifest**: Define the genre, time unit, and stat labels.
    2. **Initialize Arcs**: Create 1 main Plot Arc based on the "Immediate Situation" in the Dossier.
    3. **Populate Ledger & Advisors**: 
       - **MANDATORY**: Extract the specific figures from the DOSSIER.
       - **CASTING CHECK**: Review your list. Are there any generic names like "Senator Stone"? If so, **REPLACE THEM IMMEDIATELY** with a real historical figure or public figure that fits the archetype.
       - Create at least 2 Allies, 2 Enemies, and 2 Assets.
    4. **Generate Turn 1**: The inciting incident described in the Dossier.
    5. **Generate Choices**: Create choices that directly address the "Strategic Dilemmas".
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        maxOutputTokens: 20000,
        thinkingConfig: { thinkingBudget: 12288 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Failed to init game:", error);
    throw error;
  }
};

export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  choiceDetails: string | null,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  // We need to pass the Manifest and recent Arcs to ensure consistency
  const latestState = currentHistory[currentHistory.length - 1];
  const manifest = latestState.manifestSnapshot;

  // Compact history log
  const historyLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Stats: ${JSON.stringify(h.statsSnapshot)}`
  ).join("\n");

  const actionDescription = customInput 
    ? `Player input custom directive: "${customInput}"` 
    : `Player selected: "${playerChoiceText}".\nEXECUTION DETAILS: ${choiceDetails}`;

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVANCE SIMULATION ===

    **SIMULATION MANIFEST (DO NOT VIOLATE)**:
    ${JSON.stringify(manifest, null, 2)}

    **CURRENT ARCS (UPDATE THESE)**:
    ${JSON.stringify(latestState.arcsSnapshot, null, 2)}

    **CURRENT LEDGER (ENTITIES)**:
    ${JSON.stringify(latestState.ledgerSnapshot, null, 2)}

    HISTORY:
    ${historyLog}

    PREVIOUS NARRATIVE:
    ${latestState.narrative}

    PLAYER DECISION:
    ${actionDescription}

    TASK:
    1. **CALCULATE**: Compare Player Resources/Assets vs Enemy Power.
    2. **ADJUDICATE**: Determine Outcome Category.
    3. **UPDATE STATE**:
       - Update Arc Progress.
       - Update Entity Power/Loyalty.
       - **CASTING CHECK**: If introducing a NEW character in the narrative, ensure they are a REAL person drafted for the role, not a made-up name.
       - Update Global Stats.
    4. **NARRATE**: Write the response matching the genre "${manifest.genre}".
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        maxOutputTokens: 20000,
        thinkingConfig: { thinkingBudget: 12288 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

export const consultAdvisor = async (
    advisor: any, 
    currentContext: string,
    userQuestion: string
  ): Promise<string> => {
    const ai = getClient();
    const prompt = `
      ${ADVISOR_INSTRUCTION}

      === SCENARIO CONTEXT ===
      ${currentContext}

      === YOUR PERSONA ===
      NAME: ${advisor.name}
      ROLE: ${advisor.role}
      BIAS: ${advisor.bias} (Let this guide your tone and suggestions)

      === PLAYER QUESTION ===
      "${userQuestion}"

      RESPONSE:
    `;
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
      });
      return response.text || "No comment.";
    } catch (error) {
      return "Comm-link disrupted.";
    }
  };

