// HELPER FOR RISK FORMULA AND RANGES
const getRiskDetails = (risk: string) => {
  switch(risk) {
    case 'LOW': return { threshold: 3, label: '90% Success Rate' };
    case 'MEDIUM': return { threshold: 8, label: '65% Success Rate' };
    case 'HIGH': return { threshold: 12, label: '45% Success Rate' };
    case 'EXTREME': return { threshold: 16, label: '25% Success Rate' };
    default: return { threshold: 12, label: 'Standard Risk' };
  }
}

// Helper to determine the precise d20 ranges for outcomes
const getOutcomeRanges = (risk: string) => {
    let threshold = 12;
    if (risk === 'LOW') threshold = 3;
    if (risk === 'MEDIUM') threshold = 8;
    if (risk === 'HIGH') threshold = 12;
    if (risk === 'EXTREME') threshold = 16;

    const critFailCeiling = Math.ceil(threshold / 2) - 1;
    // Critical Failure: 1 to critFailCeiling.
    // Partial Failure: (critFailCeiling + 1) to (threshold - 1).
    // Success: threshold to 19.
    // Crit Success: 20.

    // Handle edge case where partial failure range might be empty (e.g. threshold 3 -> critFailCeiling 1. Fail: 2-2)

    return {
        critFail: `1-${Math.max(1, critFailCeiling)}`,
        fail: `${Math.max(1, critFailCeiling) + 1}-${threshold - 1}`,
        success: `${threshold}-19`,
        critSuccess: '20'
    };
};

