// === RNG LOGIC (CODE SIDE) ===
// We move this out of the LLM to ensure fair, unbiased probability.
const calculateOutcome = (risk: string): { roll: number; outcome: string; label: string } => {
    const roll = Math.floor(Math.random() * 20) + 1; // 1-20

    // Default to High Risk if unknown
    let threshold = 12; 

    if (risk === 'LOW') threshold = 3;         // 90% Success
    if (risk === 'MEDIUM') threshold = 8;      // 65% Success
    if (risk === 'HIGH') threshold = 12;       // 45% Success
    if (risk === 'EXTREME') threshold = 16;    // 25% Success

    let outcomeCategory = 'PARTIAL_FAILURE';
    let outcomeLabel = 'FAILURE';

    if (roll >= threshold) {
        // SUCCESS BRANCH
        if (roll === 20) {
             outcomeCategory = 'VICTORY';
             outcomeLabel = 'CRITICAL SUCCESS';
        } else {
             outcomeCategory = 'VICTORY';
             outcomeLabel = 'SUCCESS';
        }
    } else {
        // FAILURE BRANCH
        // We want to avoid "Partial Success" loops. 
        // If it fails, it fails.
        if (roll === 1) {
            outcomeCategory = 'CRITICAL_FAILURE';
            outcomeLabel = 'CATASTROPHIC FAILURE';
        } else if (roll < threshold / 2) {
             outcomeCategory = 'CRITICAL_FAILURE'; 
             outcomeLabel = 'FAILURE';
        } else {
             outcomeCategory = 'PARTIAL_FAILURE';
             outcomeLabel = 'PARTIAL FAILURE';
        }
    }

    return { roll, outcome: outcomeCategory, label: outcomeLabel };
};

