export const assessCustomRisk = async (
  currentHistory: HistoryEntry[],
  customInput: string
): Promise<{ risk: 'LOW' | 'MEDIUM' | 'HIGH' | 'EXTREME'; reasoning: string }> => {
  const ai = getClient();
  const latestState = currentHistory[currentHistory.length - 1];

  const prompt = `
    ROLE: Strategic Risk Assessor.

    SCENARIO CONTEXT:
    ${latestState.narrative}

    PLAYER PROPOSED ACTION:
    "${customInput}"

    TASK:
    Assess the risk of this action given the current situation.

    RISK LEVELS:
    - LOW: Routine, administrative, highly likely to succeed (90% success rate).
    - MEDIUM: Standard operation, some uncertainty (65% success rate).
    - HIGH: Dangerous, complex, combat, or controversial (45% success rate).
    - EXTREME: Moonshot, reckless, physically improbable (25% success rate).

    OUTPUT JSON:
    { "risk": "LOW"|"MEDIUM"|"HIGH"|"EXTREME", "reasoning": "short explanation" }
  `;

  try {
    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: { 
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    risk: { type: Type.STRING, enum: ['LOW', 'MEDIUM', 'HIGH', 'EXTREME'] },
                    reasoning: { type: Type.STRING }
                },
                required: ["risk", "reasoning"]
            }
        }
    });

    const text = response.text;
    if (!text) return { risk: 'HIGH', reasoning: 'Assessment unavailable.' };
    return JSON.parse(text) as { risk: 'LOW' | 'MEDIUM' | 'HIGH' | 'EXTREME'; reasoning: string };
  } catch (e) {
    console.warn("Risk assessment failed, defaulting to HIGH", e);
    return { risk: 'HIGH', reasoning: 'Manual override required.' };
  }
};

export const processTurn = async (
  currentHistory: HistoryEntry[],
  playerChoiceText: string,
  choiceDetails: string | null,
  choiceMetadata: { risk: string; type: string } | null,
  customInput?: string
): Promise<TurnData> => {
  const ai = getClient();

  const latestState = currentHistory[currentHistory.length - 1];
  const manifest = latestState.manifestSnapshot;

  const historyLog = currentHistory.map(h => 
    `[Turn ${h.turnNumber} | ${h.year}] Event: ${h.eventTitle}. Choice: ${h.userChoice || "None"}. Goal Status: ${h.goalSnapshot.turnsRemaining} turns left on "${h.goalSnapshot.description}".`
  ).join("\n");

  const actionDescription = customInput 
    ? `Player input custom directive: "${customInput}"\nCONTEXTUAL ANALYSIS: ${choiceDetails || 'None'}` 
    : `Player selected: "${playerChoiceText}".\nEXECUTION DETAILS: ${choiceDetails}`;

  // === CALCULATE RNG OUTCOME (CODE SIDE) ===
  const riskProfile = choiceMetadata ? choiceMetadata.risk : 'HIGH'; // Default to High for custom input
  const rngResult = calculateOutcome(riskProfile);

  const riskContext = `
    === MANDATORY RESOLUTION ENGINE ===
    RISK PROFILE: ${riskProfile}
    D20 ROLL: ${rngResult.roll}/20
    REQUIRED OUTCOME: ${rngResult.outcome} (${rngResult.label})

    INSTRUCTIONS:
    1. You MUST accept this outcome. Do not change it.
    2. Narrate the events that lead to this specific result.
    3. In the 'executionAnalysis' JSON, set 'rollValue' to "${rngResult.roll}/20" and 'outcomeCategory' to "${rngResult.outcome}".
  `;

  // AGGREGATE KNOWN ADVISORS FROM HISTORY (Character Bible)
  const knownAdvisorsMap = new Map<string, Advisor>();
  currentHistory.forEach(entry => {
    entry.advisorsSnapshot?.forEach(adv => {
       // We use name as unique key to prevent overwrites, ensuring we have a roster of all unique people encountered.
       if (!knownAdvisorsMap.has(adv.name)) {
         knownAdvisorsMap.set(adv.name, adv);
       }
    });
  });

  const knownPersonnelList = Array.from(knownAdvisorsMap.values())
    .map(a => `- ${a.name} (${a.role}) [Bias: ${a.bias}]`)
    .join("\n");

  const prompt = `
    ${SYSTEM_INSTRUCTION}

    === MISSION: ADVANCE SIMULATION ===

    **SIMULATION MANIFEST**:
    ${JSON.stringify(manifest, null, 2)}

    **CURRENT GOAL (AUDIT REQUIRED IF TURNS <= 0)**:
    ${JSON.stringify(latestState.goalSnapshot, null, 2)}

    **CURRENT LEDGER**:
    ${JSON.stringify(latestState.ledgerSnapshot, null, 2)}

    **KNOWN PERSONNEL ROSTER (CHARACTER BIBLE)**:
    ${knownPersonnelList || "None established yet."}

    INSTRUCTIONS FOR ADVISORS:
    1. Select 3-4 advisors from the ROSTER who are relevant to the current event.
    2. If a new perspective is absolutely needed (e.g. a Scientist for a plague) and not in the roster, you may recruit a new historical figure.
    3. DO NOT output two advisors with the same role/title.

    HISTORY:
    ${historyLog}

    PREVIOUS NARRATIVE:
    ${latestState.narrative}

    PLAYER DECISION:
    ${actionDescription}

    ${riskContext}

    TASK:
    1. **ADJUDICATE**: Apply the consequences of the FORCED OUTCOME defined above.
    2. **UPDATE GOAL**: 
       - Decrement \`turnsRemaining\`. 
       - If \`turnsRemaining\` <= 0 OR outcome is decisive, **POPULATE goalResult** and **GENERATE NEW GOAL**.
    3. **UPDATE STATE**: Update Arcs, Entities, Stats.
    4. **ADVISORS**: Select the 3-4 most relevant advisors for this specific turn.
    5. **NARRATE**: Write the response.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: turnSchema,
        maxOutputTokens: 20000,
        thinkingConfig: { thinkingBudget: 12288 }
      }
    });

    if (!response.text) throw new Error("No response from AI");
    return JSON.parse(response.text) as TurnData;
  } catch (error) {
    console.error("Turn processing failed:", error);
    throw error;
  }
};

