  MEDIUM: { threshold: 8, label: '65% Success Rate' },
  HIGH: { threshold: 12, label: '45% Success Rate' },
  EXTREME: { threshold: 16, label: '25% Success Rate' },
};

export const getRiskConfig = (risk: string) => {
    // Normalize string to RiskLevel key
    const r = (risk?.toUpperCase() || 'HIGH') as RiskLevel;
    return RISK_CONFIG[r] || RISK_CONFIG.HIGH;
};

export const calculateOutcome = (risk: string): { roll: number; outcome: string; label: string } => {
    const roll = Math.floor(Math.random() * 20) + 1; // 1-20
    const config = getRiskConfig(risk);
    const threshold = config.threshold;

    let outcomeCategory = 'PARTIAL_FAILURE';
    let outcomeLabel = 'FAILURE';

    if (roll >= threshold) {
        // SUCCESS BRANCH
        if (roll === 20) {
             outcomeCategory = 'VICTORY';
             outcomeLabel = 'CRITICAL SUCCESS';
        } else {
             outcomeCategory = 'VICTORY';
             outcomeLabel = 'SUCCESS';
        }
    } else {
        // FAILURE BRANCH
        // Logic: Critical Failure is the bottom 50% of the failure range, capped at Nat 1 minimum.
        // e.g. Threshold 12 (Fail 1-11). Half is 5.5. Rolls < 6 are Crit Fail.
        // e.g. Threshold 3 (Fail 1-2). Half is 1.5. Rolls < 1.5 are Crit Fail.

        const critFailThreshold = threshold / 2;

        if (roll === 1 || roll < critFailThreshold) {
            outcomeCategory = 'CRITICAL_FAILURE';
            outcomeLabel = 'CATASTROPHIC FAILURE';
        } else {
             outcomeCategory = 'PARTIAL_FAILURE';
             outcomeLabel = 'PARTIAL FAILURE';
        }
    }

    return { roll, outcome: outcomeCategory, label: outcomeLabel };
};

export const getOutcomeRanges = (risk: string) => {
    const config = getRiskConfig(risk);
    const threshold = config.threshold;

    // Reverse engineer the logic from calculateOutcome for display
    const critFailCeiling = Math.ceil(threshold / 2) - 1;
    const failCeiling = threshold - 1;

    // Handle edge case for LOW risk where failure range is tiny (1-2)
    const critFailEnd = Math.max(1, critFailCeiling);
    const failStart = critFailEnd + 1;

    return {
        critFail: `1-${critFailEnd}`,
        fail: failStart > failCeiling ? "N/A" : `${failStart}-${failCeiling}`,
        success: `${threshold}-19`,
        critSuccess: '20'
    };
};

