                    <p className="font-bold mb-1">Simulation Error</p>
                    <p className="text-sm">{error}</p>
                    <button onClick={() => setError(null)} className="mt-2 text-xs underline hover:text-white">Dismiss</button>
                  </div>
              </div>
          )}
          {!currentTurnData.gameOver && !loading && (
             <div className="mt-12 pt-8 animate-fade-in border-t border-gray-800">
                 <div className="flex justify-between items-end mb-6">
                    <div className="flex items-center gap-3">
                        <Terminal size={18} className="text-emerald-500" />
                        <h3 className="text-sm font-mono text-emerald-500 uppercase tracking-widest">Command Center</h3>
                    </div>
                    <button 
                        onClick={() => setShowLedger(!showLedger)}
                        className="text-xs font-mono text-blue-400 hover:text-blue-300 uppercase flex items-center gap-2 bg-gray-900 px-3 py-1 rounded border border-blue-900/50 hover:border-blue-500 transition-all"
                    >
                        {showLedger ? 'Hide Intel' : 'View Strategic Intel'}
                    </button>
                 </div>
                 {showLedger && <LedgerPanel ledger={currentTurnData.ledger} />}
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                    {currentTurnData.choices.map(renderChoiceButton)}
                 </div>
                 <div className="relative group">
                    <div className="absolute -inset-0.5 bg-gradient-to-r from-emerald-900 to-blue-900 rounded-lg blur opacity-20 group-hover:opacity-40 transition duration-1000"></div>
                    <div className="relative flex items-end bg-gray-950 rounded-lg border border-gray-700 shadow-inner">
                        <textarea
                            ref={textareaRef}
                            value={customInput}
                            onChange={(e) => setCustomInput(e.target.value)}
                            placeholder="Overwrite protocol with custom directive..."
                            rows={1}
                            className="w-full bg-transparent border-none rounded-lg pl-5 pr-14 py-4 focus:ring-0 text-base font-mono resize-none overflow-hidden"
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && !e.shiftKey) {
                                    e.preventDefault();
                                    if(customInput) handleTurn(customInput, null, null, true);
                                }
                            }}
                        />
                        <button 
                            onClick={() => customInput && handleTurn(customInput, null, null, true)}
                            disabled={!customInput}
                            className="absolute right-3 bottom-3 p-2 bg-emerald-900/20 text-emerald-500 hover:bg-emerald-800 hover:text-emerald-100 rounded-md transition-all disabled:opacity-0 disabled:pointer-events-none"
                        >
                            <Send size={20} />
                        </button>
                    </div>
                 </div>
             </div>
          )}
          {currentTurnData.gameOver && !loading && (
             <div className="bg-gray-800 border border-yellow-700/50 p-8 rounded-xl text-center shadow-2xl mt-12">
                <h3 className="text-3xl font-bold text-yellow-500 mb-4">Timeline Terminated</h3>
                <p className="text-gray-300 mb-8">The simulation has reached a conclusion.</p>
                <button 
                  onClick={onRestart}
                  className="bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-4 rounded-lg font-bold shadow-lg transition-transform hover:scale-105 uppercase tracking-wide text-sm"
                >
                  Initialize New Divergence
                </button>
             </div>
          )}
          <div className="h-4" />
        </div>
      </div>

      {showDebrief && currentTurnData.goalResult && (
        <MissionDebriefModal 
            result={currentTurnData.goalResult} 
            nextGoal={currentTurnData.currentGoal} 
            onContinue={() => setShowDebrief(false)}
            onTerminate={onRestart}
        />
      )}
    </div>
  );
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { TurnData, HistoryEntry, SimulationManifest, Advisor } from '../types';
import { calculateOutcome } from './mechanics';

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY environment variable is not set.");
  }
  return new GoogleGenAI({ apiKey });
};

// === UNIVERSAL SIMULATION SCHEMA ===
const entitySchema: Schema = {
  type: Type.OBJECT,
  properties: {
    id: { type: Type.STRING },
    name: { type: Type.STRING },
    type: { type: Type.STRING, enum: ['Faction', 'Asset', 'Figure', 'Threat'] },
    description: { type: Type.STRING },
    power: { type: Type.INTEGER, description: "0-100. Capability/Strength." },
    loyalty: { type: Type.INTEGER, description: "0-100. Willingness/Alignment." },
    status: { type: Type.STRING, description: "Current state (e.g. 'Mobilizing', 'Striking', 'Idle')." }
  },
  required: ["id", "name", "type", "description", "power", "loyalty", "status"]
};

const turnSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    turnNumber: { type: Type.INTEGER },
    year: { type: Type.STRING },
    eventTitle: { type: Type.STRING },

    // The Static Rulebook
    manifest: {
      type: Type.OBJECT,
      properties: {
        genre: { type: Type.STRING },
        timeUnit: { type: Type.STRING },
