          required: ["stabilityLabel", "wealthLabel", "supportLabel", "primaryStatLabel"]
        }
      },
      required: ["genre", "timeUnit", "statsConfig"]
    },

    // The Mission Objective
    currentGoal: {
      type: Type.OBJECT,
      properties: {
