                </button>
             </div>
          )}
          <div className="h-4" />
        </div>
      </div>

      {showDebrief && currentTurnData.goalResult && (
        <MissionDebriefModal 
            result={currentTurnData.goalResult} 
            nextGoal={currentTurnData.currentGoal} 
            onContinue={() => setShowDebrief(false)}
            onTerminate={onRestart}
        />
      )}
    </div>
  );
};

